// ---- Routines ----

async function GO() {
  restart: for (;;) {
    g.MIDSCREEN = div(getb(0, 33), 2);
    ++g.MIDSCREEN;
    if (g.MIDSCREEN < 32) {
      crlf();
      await TOO_NARROW();
      await quit();
    }
    putb(g.INSAVE_A, 0, 0);
    putb(g.INSAVE_B, 0, 0);
    putb(g.INSAVE_C, 0, 0);
    g.RATS = RODENTS;
    g.WINNER = PLAYER;
    await V_$REFRESH();
    crlf();
    await COPYRIGHT();
    crlf();
    await GET_KEY();
    await V_$REFRESH();
    await BOOT_SCREEN();
    await DO_MAIN_LOOP();
    continue restart;
  }
}

async function GET_KEY() {
  let x = 0;
  tell("\n[Press any key to begin.]\n");
  x = await readChar(1);
  return true;
}

async function DO_MAIN_LOOP() {
  let x = 0;
  for (;;) {
    x = await MAIN_LOOP();
  }
}

async function MAIN_LOOP() {
  let icnt = 0, ocnt = 0, num = 0, cnt = 0, obj = 0, tbl = 0, v_ = false, ptbl = 0, obj1 = 0, tmp = 0, x = 0;
  cnt = 0;
  obj = false;
  ptbl = true;
  if (!(g.HERE == g.QCONTEXT_ROOM)) {
    g.QCONTEXT = false;
  }
  g.P_WON = await PARSER();
  if (!(g.P_WON == 0)) {
    icnt = get(g.P_PRSI, P_MATCHLEN);
    ocnt = get(g.P_PRSO, P_MATCHLEN);
    if (!(g.P_IT_OBJECT == 0) && (await ACCESSIBLE$(g.P_IT_OBJECT))) {
      tmp = false;
      loop1: for (;;) {
        if ((cnt = cnt + 1) > icnt) {
          break loop1;
        } else {
          if (eq(get(g.P_PRSI, cnt), IT)) {
            put(g.P_PRSI, cnt, g.P_IT_OBJECT);
            tmp = true;
            break loop1;
          }
        }
      }
      if (tmp == 0) {
        cnt = 0;
        loop2: for (;;) {
          if ((cnt = cnt + 1) > ocnt) {
            break loop2;
          } else {
            if (eq(get(g.P_PRSO, cnt), IT)) {
              put(g.P_PRSO, cnt, g.P_IT_OBJECT);
              break loop2;
            }
          }
        }
      }
      cnt = 0;
    }
    num = ocnt == 0 ? ocnt : (ocnt > 1 ? (tbl = g.P_PRSO, icnt == 0 ? (obj = false) : (obj = get(g.P_PRSI, 1)), ocnt) : (icnt > 1 ? (ptbl = false, tbl = g.P_PRSI, obj = get(g.P_PRSO, 1), icnt) : 1));
    if ((obj == 0) && (icnt == 1)) {
      obj = get(g.P_PRSI, 1);
    }
    if (isVerb(V.WALK)) {
      v_ = await PERFORM(g.PRSA, g.PRSO);
    } else if (num == 0) {
      if ((getb(g.P_SYNTAX, P_SBITS) & P_SONUMS) == 0) {
        v_ = await PERFORM(g.PRSA);
        g.PRSO = false;
      } else if (g.LIT$ == 0) {
        await PCLEAR();
        await TOO_DARK();
      } else {
        await PCLEAR();
        tell("[There isn't anything to ");
        tmp = get(g.P_ITBL, P_VERBN);
        if (inTable(g.PRSA, g.TALKVERBS, NTVERBS)) {
          tell("talk to");
        } else if (!(g.P_MERGED == 0) || !(g.P_OFLAG == 0)) {
          printB(get(tmp, 0));
        } else {
          v_ = await WORD_PRINT(getb(tmp, 2), getb(tmp, 3));
        }
        tell(".]\n");
        v_ = false;
      }
    } else {
      x = 0;
      g.P_MULT$ = false;
      if (num > 1) {
        g.P_MULT$ = true;
      }
      tmp = false;
      loop3: for (;;) {
        if ((cnt = cnt + 1) > num) {
          if (x > 0) {
            tell("[The ");
            if (!(x == num)) {
              tell("other ");
            }
            tell("object");
            if (!(x == 1)) {
              tell("s");
            }
            tell(" that you mentioned ");
            if (!(x == 1)) {
              tell("are");
            } else {
              tell("is");
            }
            tell("n't here.]\n");
          } else if (tmp == 0) {
            await REFERRING();
          }
          break loop3;
        } else {
          if (!(ptbl == 0)) {
            obj1 = get(g.P_PRSO, cnt);
          } else {
            obj1 = get(g.P_PRSI, cnt);
          }
          if ((num > 1) || eq(get(get(g.P_ITBL, P_NC1), 0), W.ALL, W.EVERYTHING)) {
            if (obj1 == NOT_HERE_OBJECT) {
              ++x;
              continue loop3;
            } else if ((g.P_GETFLAGS == P_ALL) && (await DONT_ALL$(obj1, obj))) {
              continue loop3;
            } else if (!(await ACCESSIBLE$(obj1))) {
              continue loop3;
            } else if (obj1 == PLAYER) {
              continue loop3;
            } else {
              if (obj1 == IT) {
                if (!(hasFlag(g.P_IT_OBJECT, NOARTICLE))) {
                  tell("The ");
                }
                tell(D(g.P_IT_OBJECT));
              } else {
                if (!(hasFlag(obj1, NOARTICLE))) {
                  tell("The ");
                }
                tell(D(obj1));
              }
              tell(": ");
            }
          }
          tmp = true;
          g.PRSO = !(ptbl == 0) ? obj1 : obj;
          g.PRSI = !(ptbl == 0) ? obj : obj1;
          v_ = await PERFORM(g.PRSA, g.PRSO, g.PRSI);
          if (v_ == M_FATAL) {
            break loop3;
          }
        }
      }
    }
    if (v_ == M_FATAL) {
      g.P_CONT = false;
    }
  } else {
    g.P_CONT = false;
  }
  if (!(g.P_WON == 0) && !(v_ == M_FATAL) && !(inTable(g.PRSA, g.GAME_VERBS, NGVERBS))) {
    v_ = await CLOCKER();
  }
  g.PRSA = false;
  g.PRSO = false;
  g.PRSI = false;
  return false;
}

async function DONT_ALL$(o, i) {
  let l = 0;
  l = loc(o);
  if ((l == 0) || (o == i)) {
    return true;
  } else if (isVerb(V.TAKE)) {
    if (l == g.WINNER || l == MEEP || l == WIGHT) {
      return true;
    } else if (hasFlag(o, NOALL)) {
      return true;
    } else if (!(hasFlag(o, TAKEABLE)) && !(hasFlag(o, TRYTAKE))) {
      return true;
    } else if (hasFlag(l, CONTAINER) && !(hasFlag(l, OPENED))) {
      return true;
    } else if (!(i == 0)) {
      if (!(l == i)) {
        return true;
      } else if (await SEE_INSIDE$(i)) {
        return false;
      } else {
        return true;
      }
    } else if ((l == g.HERE) || (await SEE_INSIDE$(l))) {
      return false;
    } else {
      return true;
    }
  } else if (isVerb(V.DROP, V.PUT, V.PUT_ON, V.THROW, V.THROW_OVER)) {
    if (o == POCKET) {
      return true;
    } else if (l == POCKET) {
      return true;
    } else if (hasFlag(o, WORN)) {
      return true;
    } else if (l == g.WINNER) {
      return false;
    } else {
      return true;
    }
  } else {
    return false;
  }
}

async function ACCESSIBLE$(obj) {
  if (obj == false || obj == NOT_HERE_OBJECT) {
    return false;
  } else if (eq(await META_LOC(obj), g.WINNER, g.HERE, GLOBAL_OBJECTS)) {
    return true;
  } else if (await VISIBLE$(obj)) {
    return true;
  } else {
    return false;
  }
}

async function VISIBLE$(obj) {
  let l = 0;
  if (obj == false || obj == NOT_HERE_OBJECT) {
    return false;
  }
  l = loc(obj);
  if (l == false || l == GLOBAL_OBJECTS) {
    return false;
  } else if (l == g.HERE || l == PLAYER || l == g.WINNER) {
    return true;
  } else if ((l == LOCAL_GLOBALS) && (await GLOBAL_IN$(obj, g.HERE))) {
    return true;
  } else if ((await SEE_INSIDE$(l)) && (await VISIBLE$(l))) {
    return true;
  } else {
    return false;
  }
}

async function SEE_INSIDE$(thing) {
  if (thing == 0) {
    return false;
  } else if (!(g.P_MOBY_FLAG == 0)) {
    return true;
  } else if (hasFlag(thing, SURFACE)) {
    return true;
  } else if ((hasFlag(thing, PERSON) || hasFlag(thing, LIVING)) && !(thing == PLAYER)) {
    return true;
  } else if (hasFlag(thing, CONTAINER) && (hasFlag(thing, OPENED) || hasFlag(thing, TRANSPARENT))) {
    return true;
  } else {
    return false;
  }
}

async function META_LOC(obj) {
  for (;;) {
    if (obj == 0) {
      return false;
    } else if (loc(obj) == GLOBAL_OBJECTS) {
      return GLOBAL_OBJECTS;
    } else if (loc(obj) == ROOMS) {
      return obj;
    } else {
      obj = loc(obj);
    }
  }
}

async function V_$REFRESH(new_ = true) {
  g.OLD_HERE = false;
  g.OLD_LEN = 0;
  g.DO_WINDOW = false;
  if (!(new_ == 0)) {
    clearScreen(-1);
  }
  splitWindow(1);
  setWindow(S_WINDOW);
  bufOut(false);
  cursorSet(1, 1);
  highlight(H_INVERSE);
  await PRINT_SPACES(getb(0, 33));
  setWindow(S_TEXT);
  bufOut(true);
  highlight(H_NORMAL);
  return true;
}

async function DISPLAY_PLACE() {
  if (!(g.HERE == g.OLD_HERE)) {
    g.OLD_HERE = g.HERE;
    setWindow(S_WINDOW);
    bufOut(false);
    highlight(H_NORMAL);
    highlight(H_INVERSE);
    dirOut(D_TABLE_ON, g.SL_TABLE);
    await SAY_HERE();
    dirOut(D_TABLE_OFF);
    cursorSet(1, g.MIDSCREEN - div(g.OLD_LEN, 2));
    await PRINT_SPACES(g.OLD_LEN);
    g.OLD_LEN = get(g.SL_TABLE, 0);
    cursorSet(1, g.MIDSCREEN - div(g.OLD_LEN, 2));
    await SAY_HERE();
    setWindow(S_TEXT);
    bufOut(true);
    highlight(H_NORMAL);
  }
  return true;
}

