async function ITALICIZE(str) {
  let ptr = 2, st = 0, len = 0, char = 0;
  if (eq(getb(0, 30), 5)) {
    ++st;
  }
  dirOut(D_TABLE_ON, g.SL_TABLE);
  tell(S(str));
  dirOut(D_TABLE_OFF);
  len = get(g.SL_TABLE, 0);
  ++len;
  if (len < 2) {
    return true;
  } else if (getb(0, 1) & 8) {
    highlight(H_ITALIC);
    loop1: for (;;) {
      char = getb(g.SL_TABLE, ptr);
      if ((st == 0) && ((char == 32 || char == 46 || char == 44) || (char == 33 || char == 63 || char == 59) || (char == 58))) {
        highlight(H_NORMAL);
        printC(char);
        highlight(H_ITALIC);
      } else {
        printC(char);
      }
      if (ptr == len) {
        break loop1;
      }
      ++ptr;
    }
    highlight(H_NORMAL);
    return true;
  }
  loop2: for (;;) {
    char = getb(g.SL_TABLE, ptr);
    if ((char > 96) && (char < 123)) {
      char = char - 32;
    }
    printC(char);
    if (ptr == len) {
      break loop2;
    }
    ++ptr;
  }
  return true;
}

