async function GENERIC_DOOR_F(table) {
  let ptr = 1, door = false, len = 0, x = 0;
  if ((g.P_NAM == W.DOORS || g.P_NAM == W.DOORWAYS) || (g.P_XNAM == W.DOORS || g.P_XNAM == W.DOORWAYS)) {
    (await MORE_THAN_ONE("door"));
    return NOT_HERE_OBJECT;
  }
  len = get(table, 0);
  if (len < 2) {
    return false;
  }
  if (isVerb(V.CLOSE, V.ENTER, V.WALK_TO, V.THROUGH, V.USE, V.CROSS, V.EXIT, V.FOLLOW, V.LOOK_INSIDE, V.LOOK_OUTSIDE, V.LOOK_BEHIND)) {
    loop1: for (;;) {
      x = get(table, ptr);
      if (hasFlag(x, OPENED)) {
        if (!(door == 0)) {
          return false;
        }
        door = x;
      }
      if (++ptr > len) {
        break loop1;
      }
    }
    return door;
  } else if (isVerb(V.OPEN)) {
    loop2: for (;;) {
      x = get(table, ptr);
      if (!(hasFlag(x, OPENED))) {
        if (!(door == 0)) {
          return false;
        }
        door = x;
      }
      if (++ptr > len) {
        break loop2;
      }
    }
    return door;
  }
  return false;
}

async function HANDLE_PLACE$(inside, n_ = false, e = false, s_ = false, w_ = false, out = false) {
  let cnt = 0;
  if (!(n_ == 0)) {
    ++cnt;
  }
  if (!(e == 0)) {
    ++cnt;
  }
  if (!(s_ == 0)) {
    ++cnt;
  }
  if (!(w_ == 0)) {
    ++cnt;
  }
  if (isVerb(V.EXAMINE, V.LOOK_ON, V.LOOK_INSIDE, V.LOOK_DOWN, V.SEARCH)) {
    if (g.HERE == inside) {
      await V_LOOK();
    } else {
      await CANT_SEE_MUCH();
    }
    return true;
  } else if (isVerb(V.ENTER, V.WALK_TO, V.THROUGH)) {
    if (g.HERE == inside) {
      await ALREADY_IN();
    } else if (g.HERE == n_) {
      await DO_WALK(P.SOUTH);
    } else if (g.HERE == e) {
      await DO_WALK(P.WEST);
    } else if (g.HERE == s_) {
      await DO_WALK(P.NORTH);
    } else if (g.HERE == w_) {
      await DO_WALK(P.EAST);
    } else if (g.HERE == out) {
      await DO_WALK(P.IN);
    } else {
      await V_WALK_AROUND();
    }
    return true;
  } else if (await EXITING$()) {
    if (!(g.HERE == inside)) {
      await NOT_IN();
    } else if (cnt > 1) {
      await V_WALK_AROUND();
    } else {
      await DO_WALK(P.OUT);
    }
    return true;
  } else if ((g.NOW_PRSI$ == 0) && inTable(g.PRSA, g.MOVEVERBS, NMVERBS)) {
    await IMPOSSIBLE();
    return true;
  } else if (!(g.HERE == inside) && inTable(g.PRSA, g.TOUCHVERBS, NTOUCHES)) {
    await CANT_FROM_HERE();
    return true;
  } else {
    return false;
  }
}

