async function WINDOW(table, margin = 0) {
  let y = 4, i = 2, width = 0, lines = 0, str = 0, plines = 0;
  lines = get(table, 0);
  plines = lines;
  width = get(table, 1);
  if (margin == 0) {
    margin = g.MIDSCREEN - div(width, 2);
  }
  splitWindow(lines + 4);
  setWindow(S_WINDOW);
  bufOut(false);
  highlight(H_INVERSE);
  cursorSet(y, margin);
  await PRINT_SPACES(width);
  loop1: for (;;) {
    ++y;
    cursorSet(y, margin);
    --lines;
    if (lines == 0) {
      await PRINT_SPACES(width);
      break loop1;
    }
    str = get(table, i);
    if (str == 0) {
      await PRINT_SPACES(width);
    } else {
      printC(32);
      tell(S(str));
      printC(32);
    }
    ++i;
  }
  highlight(H_NORMAL);
  setWindow(S_TEXT);
  bufOut(true);
  splitWindow(1);
  dirOut(D_SCREEN_OFF);
  i = 2;
  crlf();
  tell("[");
  loop2: for (;;) {
    --plines;
    if (plines == 0) {
      break loop2;
    }
    str = get(table, i);
    if (!(str == 0)) {
      if (!(i == 2)) {
        printC(32);
      }
      tell(S(str));
      if (plines == 1) {
        tell("]");
      }
    }
    crlf();
    ++i;
  }
  crlf();
  dirOut(D_SCREEN_ON);
  return true;
}

