async function BUZZER_WORD$(word) {
  let tbl = 0;
  tbl = get(g.BUZZTABLE, 0);
  if (inTable(word, tbl + 2, get(tbl, 0))) {
    (await TO_DO_THING_USE("ask about", "ASK CHARACTER ABOUT"));
    return true;
  }
  tbl = get(g.BUZZTABLE, 1);
  if (inTable(word, tbl + 2, get(tbl, 0))) {
    await WAY_TO_TALK(true);
    return true;
  }
  tbl = get(g.BUZZTABLE, 2);
  if (inTable(word, tbl + 2, get(tbl, 0))) {
    tell("[", S(g.DONT), "need to use that ", D(INTNUM));
    await TO_COMPLETE();
    return true;
  }
  tbl = get(g.BUZZTABLE, 3);
  if (inTable(word, tbl + 2, get(tbl, 0))) {
    await CRUDITY();
    return true;
  }
  tbl = get(g.BUZZTABLE, 4);
  if (inTable(word, tbl + 2, get(tbl, 0))) {
    await V_WISH();
    return true;
  }
  tbl = get(g.BUZZTABLE, 5);
  if (inTable(word, tbl + 2, get(tbl, 0))) {
    tell("[Adverbs (such as \"");
    printB(word);
    tell("\") aren't needed");
    await TO_COMPLETE();
    return true;
  }
  return false;
}

async function VERB_DIR_ONLY$(wrd) {
  if (!(await WT$(wrd, PS$OBJECT)) && !(await WT$(wrd, PS$ADJECTIVE)) && ((await WT$(wrd, PS$DIRECTION)) || (await WT$(wrd, PS$VERB)))) {
    return true;
  } else {
    return false;
  }
}

async function STUFF(dest, src, max = 29) {
  let ptr = P_LEXSTART, ctr = 1, bptr = 0;
  putb(dest, 0, getb(src, 0));
  putb(dest, 1, getb(src, 1));
  for (;;) {
    put(dest, ptr, get(src, ptr));
    bptr = (ptr * 2) + 2;
    putb(dest, bptr, getb(src, bptr));
    bptr = (ptr * 2) + 3;
    putb(dest, bptr, getb(src, bptr));
    ptr = ptr + P_LEXELEN;
    if (++ctr > max) {
      return true;
    }
  }
}

async function INBUF_STUFF(dest, src) {
  let cnt = 0;
  cnt = getb(src, 0) - 1;
  for (;;) {
    putb(dest, cnt, getb(src, cnt));
    if (--cnt < 0) {
      return true;
    }
  }
}

async function INBUF_ADD(len, beg, slot) {
  let dbeg = 0, ctr = 0, tmp = 0;
  tmp = get(g.OOPS_TABLE, O_END);
  if (!(tmp == 0)) {
    dbeg = tmp;
  } else {
    dbeg = getb(g.AGAIN_LEXV, tmp = get(g.OOPS_TABLE, O_LENGTH)) + getb(g.AGAIN_LEXV, tmp + 1);
  }
  put(g.OOPS_TABLE, O_END, dbeg + len);
  loop1: for (;;) {
    putb(g.OOPS_INBUF, dbeg + ctr, getb(g.P_INBUF, beg + ctr));
    ++ctr;
    if (ctr == len) {
      break loop1;
    }
  }
  putb(g.AGAIN_LEXV, slot, dbeg);
  putb(g.AGAIN_LEXV, slot - 1, len);
  return true;
}

async function NUMBER$(ptr) {
  let cnt = 0, bptr = 0, chr = 0, sum = 0, tim = false, dollar = false;
  cnt = getb(g.P_LEXV + (ptr * 2), 2);
  bptr = getb(g.P_LEXV + (ptr * 2), 3);
  loop1: for (;;) {
    if ((cnt = cnt - 1) < 0) {
      break loop1;
    } else {
      chr = getb(g.P_INBUF, bptr);
      if (chr == 58) {
        tim = sum;
        sum = 0;
      } else if (sum > 9999) {
        return false;
      } else if (chr == CURRENCY_SYMBOL) {
        dollar = true;
      } else if ((chr > 57) || (chr < 48)) {
        return false;
      } else {
        sum = (sum * 10) + (chr - 48);
      }
      bptr = bptr + 1;
    }
  }
  await CHANGE_LEXV(ptr, W.INTNUM);
  if (sum > 9999) {
    return false;
  } else if (!(tim == 0)) {
    if (tim > 23) {
      return false;
    }
    sum = sum + (tim * 60);
  }
  g.P_DOLLAR_FLAG = dollar;
  if (!(dollar == 0) && (sum > 0)) {
    g.P_AMOUNT = sum;
    return W.MONEY;
  } else {
    g.P_NUMBER = sum;
    g.P_DOLLAR_FLAG = false;
    return W.INTNUM;
  }
}

async function ORPHAN_MERGE() {
  let cnt = (-1), temp = 0, verb = 0, beg = 0, end = 0, adj = false, wrd = 0;
  g.P_OFLAG = false;
  if (eq(await WT$(wrd = get(get(g.P_ITBL, P_VERBN), 0), PS$VERB, P1$VERB), get(g.P_OTBL, P_VERB)) || (await WT$(wrd, PS$ADJECTIVE))) {
    adj = true;
  } else if (await WT$(wrd = get(get(g.P_ITBL, P_VERBN), 0), PS$ADJECTIVE)) {
    adj = true;
  } else if ((await WT$(wrd, PS$OBJECT)) && (g.P_NCN == 0)) {
    put(g.P_ITBL, P_VERB, 0);
    put(g.P_ITBL, P_VERBN, 0);
    put(g.P_ITBL, P_NC1, g.P_LEXV + 2);
    put(g.P_ITBL, P_NC1L, g.P_LEXV + 6);
    g.P_NCN = 1;
  }
  if (!((verb = get(g.P_ITBL, P_VERB)) == 0) && (adj == 0) && !(verb == get(g.P_OTBL, P_VERB))) {
    return false;
  } else if (g.P_NCN == 2) {
    return false;
  } else if (eq(get(g.P_OTBL, P_NC1), 1)) {
    if (eq(temp = get(g.P_ITBL, P_PREP1), get(g.P_OTBL, P_PREP1)) || (temp == 0)) {
      if (!(adj == 0)) {
        put(g.P_OTBL, P_NC1, g.P_LEXV + 2);
        if (get(g.P_ITBL, P_NC1L) == 0) {
          put(g.P_ITBL, P_NC1L, g.P_LEXV + 6);
        }
        if (g.P_NCN == 0) {
          g.P_NCN = 1;
        }
      } else {
        put(g.P_OTBL, P_NC1, get(g.P_ITBL, P_NC1));
      }
      put(g.P_OTBL, P_NC1L, get(g.P_ITBL, P_NC1L));
    } else {
      return false;
    }
  } else if (eq(get(g.P_OTBL, P_NC2), 1)) {
    if (eq(temp = get(g.P_ITBL, P_PREP1), get(g.P_OTBL, P_PREP2)) || (temp == 0)) {
      if (!(adj == 0)) {
        put(g.P_ITBL, P_NC1, g.P_LEXV + 2);
        if (get(g.P_ITBL, P_NC1L) == 0) {
          put(g.P_ITBL, P_NC1L, g.P_LEXV + 6);
        }
      }
      put(g.P_OTBL, P_NC2, get(g.P_ITBL, P_NC1));
      put(g.P_OTBL, P_NC2L, get(g.P_ITBL, P_NC1L));
      g.P_NCN = 2;
    } else {
      return false;
    }
  } else if (!(g.P_ACLAUSE == 0)) {
    if (!(g.P_NCN == 1) && !adj) {
      g.P_ACLAUSE = false;
      return false;
    } else {
      beg = get(g.P_ITBL, P_NC1);
      if (!(adj == 0)) {
        beg = g.P_LEXV + 2;
        adj = false;
      }
      end = get(g.P_ITBL, P_NC1L);
      loop1: for (;;) {
        wrd = get(beg, 0);
        if (beg == end) {
          if (!(adj == 0)) {
            await ACLAUSE_WIN(adj);
            break loop1;
          } else {
            g.P_ACLAUSE = false;
            return false;
          }
        } else if ((adj == 0) && (btst(getb(wrd, P_PSOFF), PS$ADJECTIVE) || (wrd == W.ALL || wrd == W.EVERYTHING))) {
          adj = wrd;
        } else if (btst(getb(wrd, P_PSOFF), PS$OBJECT)) {
          if (wrd == g.P_ANAM) {
            await ACLAUSE_WIN(adj);
          } else {
            await NCLAUSE_WIN();
          }
          break loop1;
        }
        beg = beg + P_WORDLEN;
        if (end == 0) {
          end = beg;
          g.P_NCN = 1;
          put(g.P_ITBL, P_NC1, beg - 4);
          put(g.P_ITBL, P_NC1L, beg);
        }
      }
    }
  }
  put(g.P_VTBL, 0, get(g.P_OVTBL, 0));
  putb(g.P_VTBL, 2, getb(g.P_OVTBL, 2));
  putb(g.P_VTBL, 3, getb(g.P_OVTBL, 3));
  put(g.P_OTBL, P_VERBN, g.P_VTBL);
  putb(g.P_VTBL, 2, 0);
  for (;;) {
    if ((cnt = cnt + 1) > P_ITBLLEN) {
      g.P_MERGED = true;
      return true;
    } else {
      put(g.P_ITBL, cnt, get(g.P_OTBL, cnt));
    }
  }
  return true;
}

async function ACLAUSE_WIN(adj) {
  let x = 0;
  put(g.P_ITBL, P_VERB, get(g.P_OTBL, P_VERB));
  x = g.P_ACLAUSE + 1;
  await CLAUSE_COPY(g.P_OTBL, g.P_OTBL, g.P_ACLAUSE, x, g.P_ACLAUSE, x, adj);
  !(get(g.P_OTBL, P_NC2) == 0) && (g.P_NCN = 2, true);
  g.P_ACLAUSE = false;
  return true;
}

async function NCLAUSE_WIN() {
  await CLAUSE_COPY(g.P_ITBL, g.P_OTBL, P_NC1, P_NC1L, g.P_ACLAUSE, g.P_ACLAUSE + 1);
  !(get(g.P_OTBL, P_NC2) == 0) && (g.P_NCN = 2, true);
  g.P_ACLAUSE = false;
  return true;
}

