async function PRINT_SENTENCE() {
  let wptr = 1, wlen = 4, cptr = 5, wcnt = 1, cnt = 0, wrd = 0, len = 0, ptr = 0, char = 0;
  for (;;) {
    wrd = get(g.P_LEXV, wptr);
    if (wrd == W.QUOTE) {
    } else if (wrd == W.PERIOD || wrd == W.$ || wrd == W.$) {
      return true;
    } else if ((wrd == W.COMMA) || ((wrd == W.THEN) && eq(getb(g.P_LEXV, wlen), 1))) {
      tell(",");
    } else {
      if (!(wcnt == 1)) {
        printC(32);
      }
      len = getb(g.P_LEXV, wlen);
      ptr = getb(g.P_LEXV, cptr);
      cnt = 1;
      loop2: for (;;) {
        char = getb(g.P_INBUF, ptr);
        if ((cnt == 1) && ((wcnt == 1) || (wrd == W.NE || wrd == W.NW) || (wrd == W.SE || wrd == W.SW) || inTable(wrd, g.CAPS, NUMCAPS))) {
          char = char - 32;
        }
        if ((char > 31) && (char < 123)) {
          printC(char);
        }
        if (cnt == 1) {
          if (wrd == W.NE || wrd == W.SE) {
            tell("E");
            break loop2;
          } else if (wrd == W.NW || wrd == W.SW) {
            tell("W");
            break loop2;
          }
        }
        ++ptr;
        if (++cnt > len) {
          break loop2;
        }
      }
    }
    if (++wcnt > g.INLEN) {
      return true;
    }
    wptr = wptr + 2;
    wlen = wlen + 4;
    cptr = cptr + 4;
  }
  return true;
}

async function SAVE_INPUT() {
  let tokens = 1, lptr = 4, eptr = 1, sptr = 1, per = false, savlen = 0, cnt = 0, wlen = 0, wptr = 0, x = 0;
  savlen = getb(g.P_LEXV, 1);
  if (savlen == 0) {
    return false;
  }
  x = g.INSAVE_C;
  g.INSAVE_C = g.INSAVE_B;
  g.INSAVE_B = g.INSAVE_A;
  g.INSAVE_A = x;
  loop1: for (;;) {
    x = get(g.P_LEXV, eptr);
    if (x == W.COMMA) {
      per = false;
      putb(g.INSAVE_A, sptr, 44);
      if (++sptr > 79) {
        break loop1;
      }
    } else if (x == W.QUOTE) {
    } else if (x == W.PERIOD || x == W.$ || x == W.$) {
      if (per == 0) {
        per = true;
        putb(g.INSAVE_A, sptr, x == W.PERIOD ? 46 : (x == W.$ ? 63 : 33));
        if (++sptr > 79) {
          break loop1;
        }
      }
    } else {
      if ((tokens > 1) && (sptr < 80)) {
        putb(g.INSAVE_A, sptr, 32);
        ++sptr;
      }
      wlen = getb(g.P_LEXV, lptr);
      per = false;
      wptr = getb(g.P_LEXV, lptr + 1);
      cnt = 1;
      loop2: for (;;) {
        x = getb(g.P_INBUF, wptr);
        if ((x > 96) && (x < 123)) {
          x = x - 32;
        }
        putb(g.INSAVE_A, sptr, x);
        ++wptr;
        if ((++sptr > 79) || (++cnt > wlen)) {
          break loop2;
        }
      }
    }
    lptr = lptr + 4;
    eptr = eptr + 2;
    if (sptr > 79) {
      sptr = 79;
      break loop1;
    } else if (++tokens > savlen) {
      break loop1;
    }
  }
  putb(g.INSAVE_A, 0, sptr - 1);
  return true;
}

