async function UPDATE_SCORE(pts = 1, cr = true) {
  g.SCORE = g.SCORE + pts;
  if (g.DO_SCORE$ == 2) {
    return true;
  } else if (!(cr == 0)) {
    crlf();
  }
  highlight(H_BOLD);
  tell("[Your score just went up by ", N(pts), " point");
  if (!(pts == 1)) {
    tell("s");
  }
  tell(S(g.PTHE), "total is now ", N(g.SCORE), " out of 100.]");
  highlight(H_NORMAL);
  crlf();
  highlight(H_NORMAL);
  sound(1);
  if (g.DO_SCORE$ == 0) {
    g.DO_SCORE$ = 1;
    tell("\n[NOTE: You can turn score notification on or off at any time with the NOTIFY command.]\n");
  }
  return true;
}

