async function V_VERSION() {
  let cnt = 17, v_ = 0;
  if (await WRONG_WINNER$()) {
    return M_FATAL;
  }
  highlight(H_BOLD);
  tell("\nTRINITY\n");
  await FANTASY();
  crlf();
  await COPYRIGHT();
  crlf();
  await TRADEMARK();
  crlf();
  await V_$ID();
  await RELEASE();
  tell(" / Serial Number ");
  loop1: for (;;) {
    if ((cnt = cnt + 1) > 23) {
      break loop1;
    } else {
      printC(getb(0, cnt));
    }
  }
  crlf();
  return true;
}

