async function IDROP() {
  let l = 0;
  l = loc(g.PRSO);
  if ((l == 0) || (g.PRSO == g.WINNER || g.PRSO == ME)) {
    await IMPOSSIBLE();
    return false;
  } else if (!(l == PLAYER)) {
    tell("You'd have to take ");
    await THE_PRINT();
    if (hasFlag(l, SURFACE)) {
      tell(" off ");
    } else {
      tell(" out of ");
    }
    await THE_PRINT(l);
    tell(" first.\n");
    return false;
  } else if (hasFlag(g.PRSO, WORN) && (loc(g.PRSO) == PLAYER)) {
    await TAKE_OFF_PRSO_FIRST();
  }
  if (!(g.SUITED$ == 0) || (g.HERE == IN_WATER || g.HERE == IN_CIST || g.HERE == UNDER_WATER || g.HERE == IN_SKY || g.HERE == ON_BIRD) || ((g.HERE == PROM) && !(g.IN_DISH$ == 0)) || ((g.HERE == IN_ORBIT || g.HERE == ON_SAT || g.HERE == IN_SKY) && (g.SUITED$ == 0))) {
    await CTHE_PRINT();
    printC(32);
    await LANDS_AT_YOUR_FEET();
    return false;
  }
  move(g.PRSO, g.HERE);
  return true;
}

