async function EMPTY_PRSO(dest) {
  let obj = 0, nxt = 0, x = 0;
  obj = first(g.PRSO);
  if (obj == 0) {
    tell("There's nothing ");
    if (hasFlag(g.PRSO, SURFACE)) {
      tell("on ");
    } else {
      tell("in ");
    }
    await THE_PRINT();
    tell(S(g.PERIOD));
    return true;
  }
  g.P_MULT$ = true;
  loop1: for (;;) {
    if (!(hasFlag(obj, NOARTICLE))) {
      tell("The ");
    }
    tell(D(obj), ": ");
    if (dest == PLAYER) {
      x = await PERFORM(V.TAKE, obj, g.PRSO);
      if (x == M_FATAL) {
        break loop1;
      }
    } else if (dest == GROUND || dest == FLOOR) {
      if (hasFlag(g.PRSO, PLURAL)) {
        tell("They ");
      } else {
        tell("It ");
      }
      await LANDS_AT_YOUR_FEET();
    } else if ((((await WEIGHT(dest)) + (await WEIGHT(obj))) - getProp(dest, P.SIZE)) > getProp(dest, P.CAPACITY)) {
      tell("There isn't enough room ");
      if (hasFlag(dest, CONTAINER)) {
        tell("in ");
      } else {
        tell("on ");
      }
      await THE_PRINT(dest);
      tell(S(g.PERIOD));
    } else {
      move(obj, dest);
      tell("Done.\n");
    }
    obj = nxt;
    if (obj == 0) {
      break loop1;
    }
  }
  g.P_MULT$ = false;
  return true;
}

