async function V_WALK() {
  let pt = 0, pts = 0, str = 0, obj = 0, rm = 0;
  if (!(g.FLIP$ == 0) && !(g.P_WALK_DIR == 0) && hasFlag(g.HERE, SHADOWY)) {
    g.PRSO = g.PRSO == P.EAST ? P.WEST : (g.PRSO == P.WEST ? P.EAST : (g.PRSO == P.SE ? P.SW : (g.PRSO == P.SW ? P.SE : (g.PRSO == P.NE ? P.NW : (g.PRSO == P.NW ? P.NE : g.PRSO)))));
  }
  if (g.P_WALK_DIR == 0) {
    if (!(g.PRSO == 0)) {
      tell("[Presumably, you mean WALK TO ");
      await THE_PRINT();
      tell(".", S(g.BRACKET));
      await PERFORM(V.WALK_TO, g.PRSO);
    } else {
      await V_WALK_AROUND();
    }
    return true;
  }
  pt = getPropAddr(g.HERE, g.PRSO);
  if (!(pt == 0)) {
    pts = propSize(pt);
    if (pts == UEXIT) {
      rm = get(pt, REXIT);
      await FLY_TO$(rm);
      await GOTO(rm);
      return true;
    } else if (pts == NEXIT) {
      tell(S(get(pt, NEXITSTR)), "\n");
      return M_FATAL;
    } else if (pts == FEXIT) {
      rm = await apply(get(pt, FEXITFCN));
      if (rm == 0) {
        return M_FATAL;
      } else {
        await GOTO(rm);
        return true;
      }
    } else if (pts == CEXIT) {
      if (globalValue(getb(pt, CEXITFLAG))) {
        await GOTO(get(pt, REXIT));
        return true;
      }
      str = get(pt, CEXITSTR);
      if (!(str == 0)) {
        tell(S(str), "\n");
        return M_FATAL;
      } else {
        await CANT_GO();
        return M_FATAL;
      }
    } else if (pts == DEXIT) {
      obj = get(pt, DEXITOBJ);
      str = get(pt, DEXITSTR);
      if (hasFlag(obj, OPENED)) {
        await GOTO(get(pt, REXIT));
        return true;
      } else if (!(str == 0)) {
        tell(S(str), "\n");
        await THIS_IS_IT(obj);
        return M_FATAL;
      } else {
        await ITS_CLOSED(obj);
        return M_FATAL;
      }
    } else {
      return false;
    }
  } else if ((g.P_WALK_DIR == P.OUT) && !(hasFlag(g.HERE, INDOORS))) {
    tell(S(g.YOURE_ALREADY), "outside.\n");
    return M_FATAL;
  } else if ((g.P_WALK_DIR == P.IN) && hasFlag(g.HERE, INDOORS)) {
    tell(S(g.YOURE_ALREADY), "inside.\n");
    return M_FATAL;
  } else {
    await CANT_GO();
    return M_FATAL;
  }
}

