async function REPORT_SUNSET(bw = false) {
  crlf();
  if (!(hasFlag(SUN, TOUCHED))) {
    tell("Shadows lengthen in the gathering dusk. ");
  }
  tell("You pause to watch as the sun touches the ");
  if (bw == 0) {
    await SAY_WEST();
  } else {
    await SAY_EAST();
  }
  tell("ern ", D(HORIZON));
  if (hasFlag(SUN, TOUCHED)) {
    tell(" and sinks from view, while its mirror image rises in the ");
    if (bw == 0) {
      await SAY_EAST();
    } else {
      await SAY_WEST();
    }
    printS(g.PERIOD);
    return true;
  }
  setFlag(SUN, TOUCHED);
  tell(", painting the clouds with a fiery glow that spreads across the sky.\n\nWait a minute.\n\nThe sky is getting ");
  (await ITALICIZE("brighter."));
  tell(" You rub your eyes and blink as the ", D(DMOUNTS), " and ", D(TREETOPS), " magically emerge from darkness, suffused in a golden light swelling somewhere behind you...\n\nAnother sun is rising! You turn east and west, gaping with astonishment as the twin orbs rise and set in perfect synchronization. For a moment, both are bisected by the ", D(HORIZON), ", casting double ", D(DSHADOW), "s that cross the ground in fantastic patterns. Then the ");
  if (bw == 0) {
    await SAY_WEST();
  } else {
    await SAY_EAST();
  }
  tell("ern sun sinks from view, and the ");
  if (bw == 0) {
    await SAY_EAST();
  } else {
    await SAY_WEST();
  }
  tell("ern sun rises to command the morning.\n");
  return true;
}

