async function I_LUMP(v_ = false) {
  let obj = false, x = 0, y = 0;
  if (!(v_ == 0)) {
  } else if (!(await VISIBLE$(LUMP))) {
    clearFlag(LUMP, SEEN);
    return false;
  }
  x = first(PLAYER);
  loop1: for (;;) {
    if ((x == 0) || !(obj == 0)) {
      break loop1;
    } else if (x == LUMP) {
    } else if (hasFlag(x, FERRIC)) {
      obj = x;
      break loop1;
    } else if (await SEE_ANYTHING_IN$(x)) {
      y = first(x);
      loop2: for (;;) {
        if (y == 0) {
          break loop2;
        } else if (y == LUMP) {
        } else if (hasFlag(y, FERRIC)) {
          obj = y;
          break loop2;
        }
        y = next(y);
      }
    }
    x = next(x);
  }
  if (obj == 0) {
    return false;
  } else if (!(v_ == 0)) {
  } else if (hasFlag(LUMP, SEEN)) {
    clearFlag(LUMP, SEEN);
    return false;
  } else if (prob(25)) {
    return false;
  }
  x = loc(obj);
  setFlag(LUMP, SEEN);
  tell("\nYou can feel ");
  if (x == PLAYER) {
    await THE_PRINT(obj);
  } else {
    tell("something ");
    if (hasFlag(x, SURFACE)) {
      tell(" on ");
    } else {
      tell(" in ");
    }
    await THE_PRINT(x);
  }
  tell(" pulling towards the ", D(LUMP), S(g.PERIOD));
  return true;
}

