async function BWOMAN_F(context = false) {
  let y = false, cnt = 0, tbl = 0, x = 0;
  if (context == M_WINNER) {
    if (!(g.RAID$ == 0)) {
      await DIN_DROWNS();
      return true;
    } else if (isVerb(V.TELL_ABOUT)) {
      if (g.PRSO == ME) {
        await ASK_BWOMAN_ABOUT(g.PRSI);
        return true;
      }
      await BWOMAN_SNORTS();
      return true;
    } else if (isVerb(V.ASK_ABOUT)) {
      if (g.PRSO == ME) {
        tell("\"Why not tell me about ");
        await THEI_PRINT();
        tell(" ", D(ME), "?\" scoffs the ", D(BWOMAN), S(g.PERIOD));
        return true;
      }
      await BWOMAN_SNORTS();
      return true;
    } else if (isVerb(V.ASK_FOR)) {
      if (g.PRSO == ME) {
        tell("\"I won't beg from the likes o' you,\" sniffs the ", D(BWOMAN), S(g.PERIOD));
        return true;
      }
      await BWOMAN_SNORTS();
      return true;
    } else if (isVerb(V.WHAT, V.WHO, V.WHERE)) {
      await ASK_BWOMAN_ABOUT(g.PRSO);
      return true;
    } else if (isVerb(V.SGIVE, V.SSELL, V.SSHOW) && (g.PRSI == GBAG)) {
      if (g.PRSO == ME) {
        await NOT_A_FARTHING();
        return true;
      }
      await BWOMAN_SNORTS();
      return true;
    } else if (isVerb(V.GIVE, V.SELL, V.SHOW) && (g.PRSO == GBAG)) {
      if (g.PRSI == ME) {
        await NOT_A_FARTHING();
        return true;
      }
      await BWOMAN_SNORTS();
      return true;
    }
    await DIN_DROWNS();
    return true;
  } else if (!(g.NOW_PRSI$ == 0)) {
    if (isVerb(V.THROW, V.THROW_OVER)) {
      await BAD_COO();
      return true;
    } else if (isVerb(V.GIVE, V.SHOW)) {
      setFlag(BWOMAN, SEEN);
      if (!(g.RAID$ == 0)) {
        tell("She's too frightened to respond.\n");
        return true;
      } else if (g.PRSO == COIN) {
        remove(COIN);
        move(GBAG, LOCAL_GLOBALS);
        clearFlag(COIN, TAKEABLE);
        move(SCOIN, BWOMAN);
        g.P_IT_OBJECT = SCOIN;
        move(BAG, BWOMAN);
        tell("\"Bless yer,\" coos the ", D(BWOMAN), ", taking your money with a practiced snatch. \"Twenty p's the change.\" She holds out a ", D(BAG), " and a ", D(SCOIN), " for you.\n");
        if (g.TR$ == 0) {
          await UPDATE_SCORE();
        }
        return true;
      } else if (g.PRSO == SCOIN) {
        await NOT_A_FARTHING();
        return true;
      } else if (g.PRSO == CREDIT_CARD) {
        tell("\"I ain't Harrod's, dearie. Thirty p.\"\n");
        return true;
      } else if (isVerb(V.SHOW)) {
        return false;
      }
      await CTHEI_PRINT();
      tell(" shakes her head. \"Keep it, dearie.\"\n");
      return true;
    }
    return false;
  } else if (isVerb(V.ASK_ABOUT)) {
    if (!(g.RAID$ == 0)) {
      await DIN_DROWNS();
      return true;
    }
    await ASK_BWOMAN_ABOUT(g.PRSI);
    return true;
  } else if (isVerb(V.EXAMINE)) {
    if (g.RAID$ == 0) {
      tell("You get the feeling that she's been selling crumbs on this same bench, year after year, since well before you were born. Her face is lined with care for her feathered charges, who perch on her round shoulders without fear.\n");
      return true;
    }
    tell("She's obviously terrified by all the sirens and commotion.\n");
    return true;
  } else if (isVerb(V.ASK_FOR)) {
    if (!(g.RAID$ == 0)) {
      await DIN_DROWNS();
      return true;
    }
    setFlag(BWOMAN, SEEN);
    if (g.PRSI == GBAG || g.PRSI == BAG || g.PRSI == EBAG) {
      tell("\"A rare bargain at thirty p.\"\n");
      return true;
    } else if (hasFlag(g.PRSI, TAKEABLE)) {
      tell("\"I ain't got no ", D(g.PRSI), ", ducky.\"\n");
      return true;
    }
    tell("\"I couldn't give you that!\" laughs the ", D(g.PRSO), S(g.PERIOD));
    return true;
  } else if (inTable(g.PRSA, g.HURTVERBS, NHVERBS)) {
    await BAD_COO();
    return true;
  } else {
    return false;
  }
}

