async function ASK_BWOMAN_ABOUT(obj) {
  let q = false, cnt = 0, tbl = 0, x = 0, v_ = 0;
  setFlag(BWOMAN, SEEN);
  if (obj == GTRINITY || obj == PLUTONIUM) {
    if (getb(0, 33) < 79) {
      await CTHE_PRINT(BWOMAN);
      tell(" just smiles.\n");
      return true;
    }
    await V_$CREDITS();
    return true;
  } else if (hasFlag(obj, TOLD)) {
    await CTHE_PRINT(BWOMAN);
    tell(" scowls. \"Pay attention, ducky! I told ye once already.\"\n");
    return true;
  }
  v_ = await VISIBLE$(obj);
  cnt = get(g.BWOMAN_SUBJECTS, 0);
  loop1: for (;;) {
    tbl = get(g.BWOMAN_SUBJECTS, cnt);
    x = get(tbl, 0);
    if (x == obj) {
      if ((v_ == 0) && hasFlag(obj, TAKEABLE)) {
      } else {
        setFlag(obj, TOLD);
        tell("\"", S(get(tbl, 1)));
        if (prob(50)) {
          tell(".\"\n");
          return true;
        }
        tell(",\" replies the ", D(BWOMAN), S(g.PERIOD));
        return true;
      }
    }
    if (--cnt < 1) {
      break loop1;
    }
  }
  if (obj == WRISTWATCH) {
    await CTHE_PRINT(BWOMAN);
    if (W.TIME == get(g.P_NAMW, 1) || W.TIME == get(g.P_OFW, 1)) {
      tell(" sighs. \"Time.\"\n");
      return true;
    }
    tell(" sniffs. \"Looks cheap.\"\n");
    return true;
  } else if (obj == RUBY) {
    setFlag(obj, TOLD);
    await CTHE_PRINT(BWOMAN);
    if (g.RUBYROOM == BROAD_WALK) {
      tell(" gives you a sad smile. \"Not to worry, dear,\" she sighs. \"Ye'll get it back by and by.\"\n");
      return true;
    }
    tell(" peers at you closely. \"'Ave ye seen one?\" she whispers. \"Wouldn't let it out o' my sight if I was you.\"\n");
    return true;
  } else if (obj == MEEP) {
    setFlag(obj, TOLD);
    await CTHE_PRINT(BWOMAN);
    if (g.RUBYROOM == BROAD_WALK) {
      tell(" giggles. \"Fast, ain't he?\"\n");
      return true;
    }
    tell(" gives you a sharp look, but doesn't reply.\n");
    return true;
  } else if (!(v_ == 0) || (loc(obj) == GLOBAL_OBJECTS) || (await GLOBAL_IN$(obj, BROAD_WALK))) {
    setFlag(obj, TOLD);
    if (prob(50)) {
      q = true;
      await CTHE_PRINT(BWOMAN);
      tell(" shrugs. ");
    }
    tell("\"");
    if (prob(50)) {
      tell("You know as much as I do");
    } else {
      tell("Don't know nothin' you don't");
    }
    if (prob(50)) {
      tell(", hon");
    }
    if (!(q == 0) || prob(50)) {
      tell(".\"\n");
      return true;
    }
    tell(",\" shrugs the ", D(BWOMAN), S(g.PERIOD));
    return true;
  }
  if (prob(50)) {
    q = true;
    await CTHE_PRINT(BWOMAN);
    tell(" scowls. ");
  }
  tell("\"Don't know what you're talkin' 'bout, ducky");
  if (!(q == 0) || prob(50)) {
    tell(".\"\n");
    return true;
  }
  tell(",\" scowls the ", D(BWOMAN), S(g.PERIOD));
  return true;
}

