async function BOY_F(context = false) {
  if (!(g.NOW_PRSI$ == 0)) {
    if (isVerb(V.GIVE, V.SHOW, V.FEED)) {
      tell("The boy is too preoccupied with his music to notice your offer.\n");
      return true;
    }
    return false;
  } else if (isVerb(V.FOLLOW, V.WHERE) && hasFlag(g.PRSO, CHILLY)) {
    tell("You'd never find him in this crowd.\n");
    return true;
  } else if (isVerb(V.EXAMINE, V.WATCH)) {
    await I_BOY(false);
    return true;
  } else if (await HANDLE_BOY$()) {
    return true;
  } else if (isVerb(V.ALARM, V.TOUCH, V.KICK, V.KNOCK, V.KISS, V.SQUEEZE, V.HIT, V.TOUCH_TO, V.MOVE, V.PUSH, V.PULL, V.RAISE, V.TAKE, V.SHAKE)) {
    await ANNOY_BOY();
    return true;
  } else if (inTable(g.PRSA, g.TALKVERBS, NTVERBS)) {
    await CTHE_PRINT(BOY);
    tell(" doesn't respond", S(g.AS_IF), "he can't hear you.\n");
    return M_FATAL;
  } else {
    return false;
  }
}

async function HANDLE_BOY$() {
  if (isVerb(V.WAVE_AT, V.YELL)) {
    await CTHE_PRINT();
    tell(" does his best to ignore you.\n");
    return true;
  } else if (isVerb(V.LISTEN)) {
    await HEAR_GIANT_MUSIC();
    return true;
  } else if (isVerb(V.SMELL)) {
    tell("The boy is old enough to use deodorant, but obviously doesn't.\n");
    return true;
  } else if (isVerb(V.RAPE, V.UNDRESS)) {
    await RAPE_SCOUT();
    return true;
  } else {
    return false;
  }
}

async function GIANT_F(context = false) {
  if (!(g.NOW_PRSI$ == 0)) {
    if (isVerb(V.GIVE, V.SHOW, V.FEED)) {
      await BOY_NO_HEED();
      return true;
    } else if (isVerb(V.THROW, V.THROW_OVER)) {
      remove(g.PRSO);
      await CTHE_PRINT();
      tell(" hits the ", D(g.PRSI), ", slides off harmlessly and disappears in the dish.\n\n");
      await HURT_GIANT();
      return true;
    } else if (isVerb(V.PUT_ON)) {
      await PRSO_SLIDES_OFF_PRSI();
      return true;
    }
    return false;
  } else if (isVerb(V.EXAMINE)) {
    tell("The boy measures approximately forty feet from head to toe, and probably weighs several tons. He's wearing a pair of stereo ", D(PHONES), S(g.PERIOD));
    return true;
  } else if (await HANDLE_BOY$()) {
    return true;
  } else if (inTable(g.PRSA, g.TALKVERBS, NTVERBS)) {
    await BOY_NO_HEED();
    return M_FATAL;
  } else if (inTable(g.PRSA, g.MOVEVERBS, NMVERBS)) {
    tell("Forget it. This kid is ");
    (await ITALICIZE("big."));
    crlf();
    return true;
  } else if (isVerb(V.TOUCH, V.KICK, V.CUT, V.RIP, V.KILL, V.KNOCK, V.SHAKE, V.SQUEEZE, V.BITE)) {
    await HURT_GIANT();
    return M_FATAL;
  } else if (isVerb(V.WALK_TO, V.CLIMB_ON, V.STAND_ON, V.SIT, V.CLIMB_UP, V.CLIMB_OVER, V.RIDE)) {
    if (!(g.IN_DISH$ == 0)) {
      await EXIT_DISH_FIRST();
      return true;
    }
    await CTHE_PRINT();
    tell(" picks you off his clothes like an insect, and tosses you absently over his shoulder");
    await THROW_TO_CHASM();
    return M_FATAL;
  } else {
    return false;
  }
}

