async function SHOW_TO_MEEP(obj) {
  let x = 0;
  setFlag(MEEP, SEEN);
  if (obj == INTDIR || obj == RIGHT || obj == LEFT) {
    if ((g.P_DIRECTION == P.NE) && (g.HERE == S100) && hasFlag(TKEY, SEEN) && !(hasFlag(TKEY, TOUCHED))) {
      obj = TKEY;
    } else {
      await LOOKS_INTDIR(MEEP);
      return true;
    }
  } else if ((obj == 0) || !(await VISIBLE$(obj))) {
    await PERPLEXED(MEEP);
    return true;
  }
  if (await MEEP_GETS_TKEY$(obj)) {
    return true;
  }
  tell(S(g.CTHEMEEP));
  if (loc(obj) == MEEP) {
    move(obj, loc(MEEP));
    tell("drops ");
    await THE_PRINT(obj);
    if (loc(MEEP) == g.HERE) {
      tell(" at your feet");
    }
    printS(g.PERIOD);
    return true;
  } else if (!(g.APPETITE == 0)) {
    await BUSY_EATING();
    return true;
  } else if ((loc(MEEP) == g.HERE) && (loc(obj) == g.HERE) && hasFlag(obj, TAKEABLE) && (getProp(obj, P.SIZE) < 4)) {
    x = first(MEEP);
    if (!(x == 0)) {
      move(x, g.HERE);
      tell("drops ");
      await THE_PRINT(x);
      tell(", ");
    }
    tell("picks up ");
    await THE_PRINT(obj);
    tell(" and drops it at your feet.\n");
    return true;
  }
  tell("glances at ");
  await THE_PRINT(obj);
  tell(", turns back to you and cocks its head as if to say, \"So?\"\n");
  return true;
}

async function DOG_F() {
  if ((await NOUN_USED$(W.HELLHOUND, W.ALEXIS, W.WOLF)) || (await ADJ_USED$(W.HELL))) {
    await V_WISH();
    return M_FATAL;
  }
  setFlag(DOG, SEEN);
  if (!(g.NOW_PRSI$ == 0)) {
    if (isVerb(V.SHOW)) {
      tell("The sleeping animal exhibits no interest.\n");
      return true;
    } else if (isVerb(V.GIVE, V.FEED)) {
      move(g.PRSO, W100);
      clearFlag(g.PRSI, SEEN);
      tell("You deposit ");
      await THE_PRINT();
      tell(" under the sleeping dog's nose.\n");
      return true;
    } else if (isVerb(V.THROW, V.THROW_OVER)) {
      move(g.PRSO, g.HERE);
      tell("You toss ");
      await THE_PRINT(g.PRSO);
      if (isVerb(V.THROW_OVER)) {
        tell(" over ");
      } else {
        tell(" at ");
      }
      tell("the sleeping dog. Luckily, your pitching arm is no better than your sense of diplomacy, and ");
      await THE_PRINT(g.PRSO);
      tell(" falls short of its target by several feet.\n");
      return true;
    }
    return false;
  } else if (isVerb(V.EXAMINE, V.WATCH)) {
    tell("You're looking at a hundred and ten pounds of hard, flea-bitten muscle, leashed to the ", D(BHOUSE), " with a chain of the type used to moor ocean liners. Good thing it's sleeping.\n");
    return true;
  } else if (inTable(g.PRSA, g.TALKVERBS, NTVERBS)) {
    if (!(hasFlag(g.PRSO, TOUCHED))) {
      await ALMOST_WAKE_DOG();
      return M_FATAL;
    }
    await WAKE_DOG();
    return M_FATAL;
  } else if (isVerb(V.TOUCH, V.SQUEEZE, V.SHAKE, V.KISS, V.ADJUST, V.RAISE, V.PUSH, V.PULL)) {
    if (!(hasFlag(g.PRSO, TOUCHED))) {
      await ALMOST_WAKE_DOG(true);
      return true;
    }
    await WAKE_DOG(true);
    return true;
  } else if (isVerb(V.HIT, V.CUT, V.RIP, V.KILL, V.KICK)) {
    tell("Boldly, fearlessly, you march up to the dozing shepherd and draw back ");
    if (isVerb(V.KICK)) {
      tell(D(FEET));
    } else if (g.PRSI == 0) {
      tell(D(HANDS));
    } else {
      await THEI_PRINT();
    }
    tell(" to deal the sleeping monster a mighty blow");
    if (!(g.PRSI == false || g.PRSI == HANDS || g.PRSI == FEET) && (getProp(g.PRSI, P.SIZE) < 3)) {
      tell(" (or as mighty a blow as you can expect from ");
      await PRINTA(g.PRSI);
      tell(")");
    }
    tell(". But the dog snorts a bit in its sleep, and you bravely scurry backwards several dozen yards.\n");
    return true;
  } else if (isVerb(V.LISTEN)) {
    await CTHE_PRINT();
    tell(" slobbers gently in its sleep.\n");
    return true;
  } else if (isVerb(V.SMELL)) {
    await CTHE_PRINT();
    tell(" could use a bath. Any volunteers?\n");
    return true;
  } else if (isVerb(V.RAPE)) {
    (await VOICE_MUTTERS("Okay, sicko"));
    await WAKE_DOG(true);
    return true;
  } else if (inTable(g.PRSA, g.TOUCHVERBS, NTOUCHES)) {
    tell("A second look at the sleeping brute", S(g.CHANGES));
    return true;
  } else {
    return false;
  }
}

