async function WIGHT_F(context = false) {
  setFlag(WIGHT, SEEN);
  if (!(g.NOW_PRSI$ == 0)) {
    if (isVerb(V.SHOW, V.POINT_AT, V.SHINE_AT)) {
      if (isVerb(V.SHINE_AT) && !(g.PRSO == SHARD || g.PRSO == LAMP)) {
        return false;
      }
      await CTHEI_PRINT();
      if (hasFlag(g.PRSO, LIGHTED)) {
        tell(" winces with pain, and covers its eye with an open claw.\n");
        return true;
      }
      tell(" scowls at ");
      await THE_PRINT();
      tell(" with profound disinterest.\n");
      return true;
    } else if (isVerb(V.GIVE, V.FEED)) {
      await CTHEI_PRINT();
      if (hasFlag(g.PRSO, LIGHTED)) {
        tell(" growls and backs away as you approach it with ");
        await THE_PRINT();
        tell(S(g.PERIOD));
        return true;
      } else if (g.PRSO == GARLIC || g.PRSO == ICE || g.PRSO == SKINK) {
        await VANISH();
        tell(" crams ");
        await THE_PRINT();
        tell(" into its mouth and belches.\n");
        return true;
      }
      move(g.PRSO, OSSUARY);
      g.P_IT_OBJECT = NOT_HERE_OBJECT;
      tell(" clutches ");
      await THE_PRINT();
      tell(" in its claws, glares at it briefly and flings it off into the darkness with a snarl.\n");
      return true;
    } else if (isVerb(V.THROW, V.THROW_OVER, V.PUSH_TO)) {
      if (await DONT_HAVE$(g.PRSO)) {
        (await YOUD_HAVE_TO("be holding", g.PRSO));
        return true;
      }
      await CTHEI_PRINT();
      tell(" dodges ");
      await THE_PRINT();
      if (hasFlag(g.PRSO, LIGHTED)) {
        move(g.PRSO, g.HERE);
        tell(" and kicks it back to you with a fearful screech.\n");
        if (g.PRSO == LAMP) {
          setFlag(g.PRSO, CHILLY);
          clearFlag(g.PRSO, LIGHTED);
          g.BEAM = 0;
          await DEQUEUE(I_HARDHAT.id);
          tell("\nYou hear a faint ");
          (await ITALICIZE("pop"));
          tell(" as the ", D(g.PRSO), " strikes the ground.\n");
          await SAY_IF_HERE_LIT();
        }
        return true;
      }
      tell(", snatches it up ");
      await THROWS_BACK(g.PRSO);
      return true;
    }
    return false;
  } else if (isVerb(V.EXAMINE, V.WATCH, V.SEARCH)) {
    tell("One of the ", D(g.PRSO), "'s eyes dangles from its socket on a moist pink nerve. The other glares back at you from the darkness of the ", D(TUNNEL));
    await WIGHT_HAS();
    printS(g.PERIOD);
    return true;
  } else if (isVerb(V.WAVE_AT, V.BOW)) {
    await CTHE_PRINT();
    tell(" responds to your gesture with a contemptuous snarl.\n");
    return true;
  } else if (isVerb(V.TOUCH, V.KNOCK, V.KICK, V.SQUEEZE, V.MOVE, V.PUSH, V.SHAKE, V.ADJUST, V.SWING)) {
    await VERY_CLOSE();
    return true;
  } else if (isVerb(V.HIT, V.KILL)) {
    if (g.PRSI == false || g.PRSI == HANDS || g.PRSI == FEET) {
      await VERY_CLOSE();
      return true;
    } else if (hasFlag(g.PRSI, LIGHTED)) {
      await CTHE_PRINT();
      tell(" backs out of your reach, snarling with fear.\n");
      return true;
    }
    await CTHE_PRINT();
    tell(" grapples ");
    await THEI_PRINT();
    tell(" away from you ");
    await THROWS_BACK(g.PRSI);
    return true;
  } else if (inTable(g.PRSA, g.TALKVERBS, NTVERBS)) {
    await WIGHT_RESPONDS();
    return M_FATAL;
  } else if (isVerb(V.KISS, V.RAPE)) {
    tell("Your gesture brings a tear to the ", D(g.PRSO), "'s eye as it recalls the tender moments of its former human existence. Then it breaks your neck with a practiced swipe of its claw.");
    await JIGS_UP();
    return M_FATAL;
  } else if (isVerb(V.SMELL)) {
    await CTHE_PRINT();
    tell(" smells as if it's been dead a long time.\n");
    return true;
  } else {
    return false;
  }
}

