async function HANDLE_GIS$() {
  if (!(g.NOW_PRSI$ == 0)) {
    if (isVerb(V.GIVE, V.SHOW, V.FEED)) {
      await CANT_FROM_HERE();
      return true;
    }
    return false;
  } else if (isVerb(V.SMELL, V.SEARCH, V.LOOK_BEHIND, V.LOOK_UNDER) || inTable(g.PRSA, g.TOUCHVERBS, NTOUCHES)) {
    await CANT_FROM_HERE();
    return true;
  } else if (await ENTERING$()) {
    await DO_WALK(P.NE);
    return true;
  } else if (!(inTable(g.PRSA, g.TALKVERBS, NTVERBS))) {
    return false;
  }
  if (g.PRSO == GIS) {
    tell("One of the ", D(g.PRSO));
  } else {
    await CTHE_PRINT();
  }
  if (!(hasFlag(GIS, SEEN))) {
    setFlag(GIS, SEEN);
    tell(" starts");
    await AT_YOUR_VOICE();
    tell("\"Who said that?\" he cries.\n\nThe ");
    if (g.PRSO == GIS) {
      tell("other ");
    } else {
      tell("surrounding ");
    }
    tell(D(GIS), " snap to alert attention, peering into the gloom. Nobody moves for a long moment. Then, one by one, they begin to relax... all but the closest GI, who stares in the ", D(INTDIR), " of the shed nervously.\n");
    return M_FATAL;
  }
  tell(" points in your ", D(INTDIR));
  await AT_YOUR_VOICE();
  tell("\"The shed!\" he cries.\n");
  await SURROUNDED();
  return M_FATAL;
}

