async function IN_BARROW_F(context = false) {
  if (context == M_LOOK) {
    tell("The ");
    if ((await VISIBLE$(LAMP)) && hasFlag(LAMP, LIGHTED)) {
      tell(D(LAMP), "'s faltering beam");
    } else if (await VISIBLE$(SHARD)) {
      tell(D(SHARD), "'s ghostly flicker");
    } else {
      tell("dim light from outside");
    }
    tell(" does little to dispel the gloom of this subterranean passage. Craggy walls bend away", S(g.TON), " and south");
    if (hasFlag(SLOPE, OPENED)) {
      tell("; chill vapors rise from a slope that descends into darkness");
    }
    printS(g.PERIOD);
    return true;
  } else if (context == M_ENTERED) {
    if (hasFlag(BARROW_DOOR, OPENED)) {
      clearFlag(BARROW_DOOR, OPENED);
      clearFlag(IN_BARROW, LIGHTED);
      g.P_IT_OBJECT = BARROW_DOOR;
      clearFlag(WIGHT, SEEN);
      g.WIGHTER = 4;
      await QUEUE(I_WIGHT.id, -1);
      tell("\nA clatter breaks the silence! You turn, and watch helplessly as a ", D(BARROW_DOOR), " crashes down across the south exit.\n");
      await SAY_IF_HERE_LIT();
    }
    if (!(g.LIT$ == 0) && hasFlag(WIGHT, NODESC)) {
      clearFlag(WIGHT, NODESC);
      tell("\nSomething just moved.\n\nYou peer uneasily beyond the pool of light around the ");
      if (hasFlag(LAMP, LIGHTED) && (await VISIBLE$(LAMP))) {
        tell(D(LAMP));
      } else {
        tell(D(SHARD));
      }
      tell(". Nothing. Then, as your eyes adjust, you descry a vaguely human outline crouched against the ", D(TUNNEL), " wall");
      await WIGHT_HAS();
      printS(g.PERIOD);
      await WIGHT_ID();
    }
    return true;
  } else {
    return false;
  }
}

