async function IN_BARROW_N() {
  if (loc(SHARD) == PLAYER) {
    clearFlag(WIGHT, SEEN);
    if (hasFlag(WIGHT, CHILLY)) {
      await WIGHT_STUMBLES();
    } else {
      setFlag(WIGHT, CHILLY);
      await WIGHT_COVERS();
      tell("bellows something awful as you pass", S(g.PCR));
    }
    return OSSUARY;
  } else if ((loc(LAMP) == PLAYER) && hasFlag(LAMP, LIGHTED)) {
    clearFlag(WIGHT, SEEN);
    await WIGHT_STUMBLES();
    return OSSUARY;
  } else if ((loc(LAMP) == g.HERE) && hasFlag(LAMP, LIGHTED)) {
    await WIGHT_BLOCKS_DESPITE(LAMP);
    return false;
  } else if (loc(SHARD) == g.HERE) {
    await WIGHT_BLOCKS_DESPITE(SHARD);
    return false;
  }
  tell("You stumble into the lightless ", D(TUNNEL), S(g.PCR));
  await WIGHT_KILLS_YOU();
  return false;
}

