async function CHASM_FALL() {
  let p_ = false, x = 0;
  if (g.HERE == ON_BLUFF) {
    x = VALLEY;
  } else {
    x = CHASM;
  }
  if (hasFlag(g.HERE, TRYTAKE)) {
    if ((loc(PARASOL) == PLAYER) && hasFlag(PARASOL, OPENED)) {
      p_ = true;
    }
    tell("You step boldly over the ", D(x), "'s brink");
    if (!(g.SUITED$ == 0) || !(p_ == 0)) {
      tell(" and float down, buoyed by the ");
      if (g.SUITED$ == 0) {
        tell("open ", D(PARASOL), ". But its cloth panels get tangled");
      } else {
        tell(D(FILM), ". But its flabby ", D(CSURFACE), " tears and pops");
      }
      tell(" in the ", D(TREETOPS), " below");
      if (!(p_ == 0) && !(g.SUITED$ == 0)) {
        tell("; the ", D(PARASOL), " tangles");
      }
      tell(", and you ");
    } else {
      tell(", and ");
    }
    tell("plummet to a painful end.");
    await JIGS_UP();
    return false;
  }
  setFlag(g.HERE, TRYTAKE);
  await TAKE_A_MOMENT_TO(x);
  return false;
}

