async function EXIT_ARBOR(dir) {
  let cnt = 0, obj = 0, x = 0;
  if (!(g.ENTERED_ARBOR == dir)) {
    if (g.FLIP$ == 0) {
      g.FLIP$ = true;
    } else {
      g.FLIP$ = false;
    }
    await RESET_SHDIRS();
    loop1: for (;;) {
      obj = get(g.FLIPPERS, cnt);
      if (obj == 0) {
        break loop1;
      }
      x = await GOT$(obj);
      if (x == 0) {
        if ((obj == WTK) && !(hasFlag(obj, TOUCHED))) {
        } else if (hasFlag(obj, FLIPPED)) {
          clearFlag(obj, FLIPPED);
        } else {
          setFlag(obj, FLIPPED);
        }
      }
      ++cnt;
    }
  }
  await FLOOR_TWISTS();
  tell("descend", S(g.PCR));
  return true;
}

