async function TOWER_PLAT_F(context = false) {
  if (context == M_LOOK) {
    tell("A metal rail is all that stands between you and a hundred-foot drop.\n\nMiles of barren ", D(GDESERT), " lie below, gray and still in the gathering dawn. Black roads radiate outward like the hands of a great clock.\n\nThis narrow ", D(TPLAT), " opens east into a metal ", D(SHACK));
    if (hasFlag(SPOT, SEEN)) {
      tell(S(g.PA), D(SPOT), " on the southwest ", D(HORIZON), " floods the ", D(PLATFORM), " in a raw white glare");
    }
    tell(S(g.PA), D(TLADDER), " is sticking up over the ", D(TPLAT), "'s edge.\n");
    return true;
  } else if (context == M_ENTERED) {
    (g.STAIR_DIR = "down");
    return false;
  } else {
    return false;
  }
}

