async function BUT_HESITATE(str) {
  tell(", but hesistate when you notice one of the ", D(GIS));
  if (g.MINUTES > 27) {
    tell(" in the ", D(TRENCHES));
  }
  tell(" fingering a ", S(str), ".\n\nDo you want to continue anyway?");
  if (!(await YES$())) {
    await NO_DETECTION();
    return false;
  }
  crlf();
  await YOU_MARCH();
  tell(" away from the safety of the shed.\n\nThe GI ");
  if ((str == "rifle")) {
    tell("with the rifle");
  } else {
    tell("drops his binoculars and");
  }
  tell(" leaps out of his ");
  if (g.MINUTES < 28) {
    tell(D(JEEP));
  } else {
    tell("trench");
  }
  tell(". \"Wha... Who the hell is ");
  (await ITALICIZE("that?"));
  tell("\"\n");
  await SURROUNDED();
  return false;
}

