async function ON_PORCH_F(context = false) {
  let l = false, r = false, b = false;
  if (context == M_LOOK) {
    if (hasFlag(LEFT_DOOR, OPENED)) {
      l = true;
    }
    if (hasFlag(RIGHT_DOOR, OPENED)) {
      r = true;
    }
    tell("You're on a raised deck attached", S(g.TOE), " side of the ", D(RANCH), ". Two ");
    if (!(l == 0) && !(r == 0)) {
      b = true;
      tell("open ");
    } else if ((l == 0) && (r == 0)) {
      b = true;
      tell("closed ");
    }
    tell("doors, ");
    if (b == 0) {
      await SAY_A_DOOR(LEFT_DOOR);
    }
    tell("one at the deck's left ", D(CORNER), " and ");
    if (b == 0) {
      await SAY_A_DOOR(RIGHT_DOOR);
    }
    tell("one at the right, lead inside. A gentle ramp slopes down to the front yard.\n");
    return true;
  } else {
    return false;
  }
}

async function SAY_A_DOOR(door) {
  tell("a");
  if (hasFlag(door, OPENED)) {
    tell("n open ");
  } else {
    tell(" closed ");
  }
  return true;
}

async function ENTER_RANCH() {
  let dest = 0;
  if (hasFlag(LEFT_DOOR, OPENED)) {
    dest = SEROOM;
    if (hasFlag(RIGHT_DOOR, OPENED)) {
      tell("[Which way do you want to go in, northwest or southwest?]\n");
      return false;
    }
  } else if (hasFlag(RIGHT_DOOR, OPENED)) {
    dest = NEROOM;
  } else {
    g.P_THEM_OBJECT = RIGHT_DOOR;
    tell("Both of the doors are closed.\n");
    return false;
  }
  tell("You step inside the ", D(RANCH), S(g.PCR));
  return dest;
}

