async function FEED_THE_BIRDS$() {
  if (g.NOW_PRSI$ == 0) {
    return false;
  } else if (isVerb(V.GIVE, V.FEED)) {
    if (g.PRSO == BAG) {
      await TAKE_CRUMBS();
      return true;
    } else {
      (await NOT_LIKELY(g.PRSI, "would be impressed by your offer"));
    }
    return true;
  } else if (isVerb(V.THROW, V.THROW_OVER) && (g.PRSO == BAG) && !(g.CCNT == 0)) {
    await TAKE_CRUMBS();
    return true;
  } else if (isVerb(V.SHOW)) {
    await CTHEI_PRINT();
    if (g.PRSO == BAG) {
      if (g.PRSI == PIGEONS) {
        tell(" strut");
      } else {
        tell(" swim");
      }
      tell(" about excitedly at the sight of ");
    } else {
      tell(" don't seem to care about ");
    }
    await THE_PRINT();
    tell(S(g.PERIOD));
    return true;
  } else {
    return false;
  }
}

