async function GENERIC_WATER_F(tbl) {
  if (g.P_IT_OBJECT == RPOND || g.P_IT_OBJECT == GRPOND || g.P_IT_OBJECT == LWATER) {
    return g.P_IT_OBJECT;
  } else if (g.HERE == ROUND_POND) {
    return RPOND;
  } else if ((g.HERE == LAN_WALK || g.HERE == LONG_WATER || g.HERE == IN_WATER) || (W.LONG == g.P_ADJ || W.LONG == g.P_XADJ)) {
    return LWATER;
  } else if ((g.HERE == BROAD_WALK) || (W.ROUND == g.P_ADJ || W.ROUND == g.P_XADJ)) {
    return GRPOND;
  } else {
    await REFERRING();
    return NOT_HERE_OBJECT;
  }
}

async function LWATER_F() {
  if (isVerb(V.FIND)) {
    if (g.HERE == LONG_WATER || g.HERE == IN_WATER) {
      await ITS_RIGHT_HERE();
      return true;
    } else if (g.HERE == LAN_WALK) {
      await SEE_IT_SPARKLE();
      return true;
    }
    await V_WALK_AROUND();
    return true;
  } else if (!(g.HERE == LAN_WALK || g.HERE == IN_WATER || g.HERE == LONG_WATER)) {
    await CANT_SEE_ANY();
    return M_FATAL;
  } else if (isVerb(V.EXAMINE, V.LOOK_ON)) {
    if (g.HERE == LONG_WATER) {
      await OPAQUE_WATER();
      return true;
    } else if (g.HERE == IN_WATER) {
      await V_LOOK();
      return true;
    } else if (g.HERE == LAN_WALK) {
      await SEE_IT_SPARKLE();
      return true;
    }
    await CANT_SEE_FROM_HERE(LWATER);
    return true;
  } else if (isVerb(V.LOOK_INSIDE, V.LOOK_UNDER, V.SEARCH)) {
    if (g.HERE == LONG_WATER || g.HERE == IN_WATER) {
      await OPAQUE_WATER();
      return true;
    }
    await CANT_SEE_FROM_HERE(LWATER);
    return true;
  } else if (await ENTERING$()) {
    if (g.HERE == LONG_WATER || g.HERE == LAN_WALK) {
      await DO_WALK(P.EAST);
      return true;
    } else if (g.HERE == IN_WATER) {
      await ALREADY_IN();
      return true;
    }
    await V_WALK_AROUND();
    return true;
  } else if (await EXITING$()) {
    if (g.HERE == IN_WATER) {
      await DO_WALK(P.WEST);
      return true;
    }
    await NOT_IN();
    return true;
  } else if (!(g.HERE == LONG_WATER || g.HERE == IN_WATER)) {
    await CANT_FROM_HERE();
    return true;
  } else if (isVerb(V.SWIM, V.DIVE, V.LEAP, V.CLIMB_DOWN, V.STAND_UNDER)) {
    await DO_WALK(g.HERE == LONG_WATER ? P.EAST : P.DOWN);
    return true;
  } else if (await HANDLE_WATER$()) {
    return true;
  } else {
    return false;
  }
}

