async function HANDLE_WATER$() {
  if (!(g.NOW_PRSI$ == 0)) {
    if (isVerb(V.TAKE, V.PUSH_TO)) {
      return false;
    } else if (inTable(g.PRSA, g.PUTVERBS, NUMPUTS)) {
      if ((g.PRSO == BALL || g.PRSO == CRANE) || ((g.PRSO == PARASOL) && hasFlag(g.PRSO, OPENED))) {
        await CTHE_PRINT();
        tell(" might float out of reach", S(g.IF_YOU_DID));
        return true;
      }
      await VANISH();
      await CTHE_PRINT();
      if (g.PRSO == OCRANE || g.PRSO == BAD_CRANE) {
        tell(" floats away ");
      } else {
        tell(" disappears ");
      }
      await SAY_IN_WATER();
      return true;
    } else if (isVerb(V.FILL) || inTable(g.PRSA, g.TOUCHVERBS, NTOUCHES)) {
      await SPLASHES();
      return true;
    }
    return false;
  } else if (isVerb(V.LOOK_UNDER)) {
    await OPAQUE_WATER();
    return true;
  } else if (await EXITING$()) {
    await NOT_IN();
    return true;
  } else if (isVerb(V.CLOSE, V.OPEN, V.OPEN_WITH)) {
    await IMPOSSIBLE();
    return true;
  } else if (isVerb(V.DRINK, V.DRINK_FROM)) {
    await CTHE_PRINT();
    await ISNT_ARENT();
    tell("very clean.\n");
    return true;
  } else if (isVerb(V.EAT, V.BITE)) {
    await IMPOSSIBLE();
    return true;
  } else if (inTable(g.PRSA, g.TOUCHVERBS, NTOUCHES)) {
    await SPLASHES();
    return true;
  } else {
    return false;
  }
}

