async function HANDLE_DIAL$(d_) {
  let g_ = false;
  if ((loc(GNOMON) == d_) && hasFlag(GNOMON, NODESC)) {
    g_ = true;
  }
  if (await NOUN_USED$(W.SHADOW)) {
    if (g_ == 0) {
      if (g.HERE == WABE) {
        tell(S(g.CANT), "see the ", D(DSHADOW), " now.\n");
        return M_FATAL;
      } else if (await DSHADOW_F()) {
        return true;
      }
    } else if (isVerb(V.EXAMINE, V.READ, V.WATCH, V.LOOK_INSIDE, V.SEARCH)) {
      await CTHE_PRINT(DSHADOW);
      await READ_DIAL();
      printS(g.PERIOD);
      return true;
    } else if (inTable(g.PRSA, g.MOVEVERBS, NMVERBS)) {
      await HOW$();
      return true;
    } else if (await ENTERING$()) {
      await V_WALK_AROUND();
      return true;
    }
  }
  if (!(g.NOW_PRSI$ == 0)) {
    return false;
  } else if (isVerb(V.EXAMINE, V.LOOK_ON, V.READ)) {
    tell("The perimeter of the ", D(g.PRSO), " is inscribed with seven curious ", D(SYMBOLS), " and a ", D(ROSE), ", with the legend \"");
    if ((g.PRSO == DIAL) || (g.FLIP$ == 0)) {
      tell("TEMPUS EDAX RERUM");
    } else {
      tell("MURER XADE SUPMET");
    }
    tell("\" emblazoned across the bottom. A ");
    if (g_ == 0) {
      tell(D(DIAL_HOLE), " is set into the center of the dial");
    } else {
      tell("triangular ", D(GNOMON), " casts a fingerlike ", D(DSHADOW), " that");
      await READ_DIAL();
    }
    if (await SEE_ANYTHING_IN$(g.PRSO)) {
      tell(". You also see ");
      await PRINT_CONTENTS(g.PRSO);
      tell(" lying on top");
    }
    printS(g.PERIOD);
    if (!(hasFlag(g.PRSO, TOUCHED))) {
      setFlag(g.PRSO, TOUCHED);
      g.DO_WINDOW = get(g.QUOTES, g.PRSO == DIAL ? CARROLL : RIMBAUD);
      return M_FATAL;
    }
    return true;
  } else if (isVerb(V.TAKE, V.MOVE, V.PUSH, V.PULL, V.RAISE, V.TURN, V.LOOSEN, V.UNSCREW, V.UNSCREW_FROM, V.TAKE_WITH)) {
    await CTHE_PRINT();
    tell(" is firmly set into the ");
    if (g.PRSO == DIAL) {
      tell(D(GROUND));
    } else {
      tell(D(PLATFORM));
    }
    tell(". It cannot be moved.\n");
    return true;
  } else if (isVerb(V.LOOK_UNDER, V.LOOK_BEHIND)) {
    await LOOK_UNDER_DIAL();
    return true;
  } else {
    return false;
  }
}

