async function HANDLE_HOLE$(d_) {
  if ((loc(GNOMON) == d_) && hasFlag(GNOMON, NODESC)) {
    await CANT_SEE_ANY();
    return M_FATAL;
  } else if (!(g.NOW_PRSI$ == 0)) {
    if (isVerb(V.PUT, V.SCREW)) {
      if (g.PRSO == GNOMON) {
        await PERFORM(V.SCREW, GNOMON, d_);
        return true;
      }
      await PRSO_WONT_FIT();
      return true;
    } else if (isVerb(V.PUT_ON)) {
      await PERFORM(V.PUT_ON, g.PRSO, d_);
      return true;
    }
    return false;
  } else if (isVerb(V.EXAMINE, V.LOOK_INSIDE)) {
    tell("The hole has a ");
    if ((g.HERE == WABE) || !(g.FLIP$ == 0)) {
      tell("lef");
    } else {
      tell("righ");
    }
    await EXAMINE_HOLE();
    return true;
  } else if (isVerb(V.REACH_IN)) {
    await TOO_SMALL();
    return true;
  } else if (isVerb(V.COVER)) {
    await PERFORM(V.PUT_ON, g.PRSO, d_);
    return true;
  } else if (inTable(g.PRSA, g.MOVEVERBS, NMVERBS)) {
    await IMPOSSIBLE();
    return true;
  } else {
    return false;
  }
}

