    tell("The seven ", D(g.PRSO), " are arranged in a circle. The series begins with a Greek omega and runs ");
    if (!(g.FLIP$ == 0)) {
      tell("counter");
    }
    tell("clockwise around the dial, ending with a Greek alpha");
    if (!(g.FLIP$ == 0)) {
      tell(". All of the ", D(g.PRSO), " are inscribed backwards");
    }
    tell(".\n\n[You'll find the ", D(g.PRSO), " reproduced on the ", D(DIAL), " in your ");
    (await ITALICIZE("Trinity"));
