async function LEVER_F() {
  if (!(g.NOW_PRSI$ == 0)) {
    return false;
  } else if (isVerb(V.EXAMINE)) {
    await CTHE_PRINT(LEVER);
    tell(" is about five feet long, and");
    await SAY_LEVER();
    crlf();
    return true;
  } else if (isVerb(V.RAISE, V.PULL, V.LOOSEN)) {
    if (g.SUN_MOVING$ == 0) {
      await RAISE_LEVER();
    } else {
      (await LEVER_MOVED("up"));
    }
    return true;
  } else if (isVerb(V.LOWER, V.PUSH)) {
    if (g.SUN_MOVING$ == 0) {
      (await LEVER_MOVED("down"));
    } else {
      await LOWER_LEVER();
    }
    return true;
  } else if (isVerb(V.MOVE, V.TURN)) {
    if (g.SUN_MOVING$ == 0) {
      await RAISE_LEVER();
    } else {
      await LOWER_LEVER();
    }
    return true;
  } else if (isVerb(V.PUSH_TO)) {
    if (g.PRSI == GROUND) {
      await PERFORM(V.LOWER, LEVER);
      return true;
    } else if (!(g.PRSI == INTDIR)) {
      await CANT_PRSA_LEVER();
      tell(" to that.\n");
      return true;
    } else if (g.P_DIRECTION == P.UP) {
      await PERFORM(V.RAISE, LEVER);
      return true;
    } else if (g.P_DIRECTION == P.DOWN) {
      await PERFORM(V.LOWER, LEVER);
      return true;
    } else {
      await CANT_PRSA_LEVER();
      tell(" in ", D(RIGHT), S(g.PERIOD));
    }
    return true;
  } else if (isVerb(V.TAKE, V.MUNG, V.SHAKE, V.KICK, V.KNOCK, V.HIT)) {
    await FIRMLY_ATTACHED(LEVER, FLOOR);
    return true;
  } else if (isVerb(V.LAMP_ON, V.LAMP_OFF, V.OPEN, V.CLOSE, V.OPEN_WITH)) {
    await HOW$();
    return true;
  } else {
    return false;
  }
}

