  crlf();
  if (st == 0) {
    tell("\"");
  } else {
    await ST_QUOTE();
    highlight(H_ITALIC);
  }
  tell("This way,");
  highlight(H_NORMAL);
  if (st == 0) {
    tell("\"");
  } else {
    await ST_QUOTE();
  }
  tell(" the voice urges. ");
  if (st == 0) {
    tell("\"");
  } else {
    await ST_QUOTE();
    highlight(H_ITALIC);
  }
  tell("Be quick.");
  highlight(H_NORMAL);
  if (st == 0) {
    tell("\"");
  } else {
    await ST_QUOTE();
  }
  await ARTICULATES();
  tell("\"No!\" your mind shudders. \"That's not a ", D(INTDIR), "!\"\n\n");
  if (st == 0) {
    tell("\"");
  } else {
    await ST_QUOTE();
    highlight(H_ITALIC);
  }
  tell("It's a perfectly legitimate ", D(INTDIR), ",");
  highlight(H_NORMAL);
  if (st == 0) {
    tell("\"");
  } else {
    await ST_QUOTE();
  }
  tell(" retorts the voice with cold amusement. ");
  if (st == 0) {
    tell("\"");
  } else {
    await ST_QUOTE();
    highlight(H_ITALIC);
  }
  tell("Now come along.");
  highlight(H_NORMAL);
  if (st == 0) {
    tell("\"");
  } else {
    await ST_QUOTE();
  }
  await CARRIAGE_RETURNS();
  clearScreen(-1);
  splitWindow(14);
  setWindow(S_WINDOW);
  bufOut(false);
  cursorSet(10, 25);
  await BIG_TRINITY();
  cursorSet(12, 29);
