async function THRU_DOOR$(out, in_) {
  if (g.NOW_PRSI$ == 0) {
    return false;
  } else if (!(isVerb(V.PUT, V.THROW))) {
    return false;
  } else if (!(hasFlag(g.PRSI, OPENED))) {
    await CTHE_PRINT();
    tell(" strikes the closed door and ");
    await LANDS_AT_YOUR_FEET();
    return true;
  } else if ((g.PRSO == PARASOL) && hasFlag(g.PRSO, OPENED)) {
    (await YOUD_HAVE_TO("close", g.PRSO));
    return true;
  }
  if (g.HERE == AT_FALLS || g.HERE == ON_MOOR) {
    remove(g.PRSO);
  } else if (g.HERE == out) {
    move(g.PRSO, in_);
  } else if (g.HERE == in_) {
    move(g.PRSO, out);
  } else {
    remove(g.PRSO);
  }
  g.P_IT_OBJECT = NOT_HERE_OBJECT;
  await CTHE_PRINT();
  tell(" disappears through the open door.\n");
  return true;
}

async function HANDLE_TSDOOR$(out) {
  if (!(g.NOW_PRSI$ == 0)) {
    return false;
  } else if (isVerb(V.EXAMINE)) {
    tell("The");
    await OPEN_CLOSED(g.PRSO);
    tell(" is of stately residential design.\n");
    return true;
  } else if (isVerb(V.LOOK_INSIDE, V.LOOK_BEHIND, V.LOOK_OUTSIDE) && hasFlag(g.PRSO, OPENED) && (g.HERE == out)) {
    await UNEASY_DOOR();
    return true;
  } else if (isVerb(V.OPEN, V.OPEN_WITH, V.SHAKE, V.RAISE, V.SQUEEZE, V.LOOSEN) && !(hasFlag(g.PRSO, OPENED))) {
    await PRSO_WONT_BUDGE();
    return true;
  } else if (isVerb(V.CLOSE) && hasFlag(g.PRSO, OPENED)) {
    tell("That's odd. ");
    await PRSO_WONT_BUDGE();
    return true;
  } else if (isVerb(V.REACH_IN)) {
    if (hasFlag(g.PRSO, OPENED)) {
      tell("You feel a gentle but firm pressure.\n");
      return true;
    }
    await ITS_CLOSED(g.PRSO);
    return true;
  } else if (isVerb(V.UNLOCK)) {
    await CTHE_PRINT();
    tell(" doesn't have a keyhole.\n");
    return true;
  } else if (await ENTERING$()) {
    await DO_WALK(P.IN);
    return true;
  } else if (await EXITING$()) {
    await NOT_IN();
    return true;
  } else {
    return false;
  }
}

