async function HANDLE_SOAPY_WATER$() {
  if (!(g.NOW_PRSI$ == 0)) {
    if (inTable(g.PRSA, g.PUTVERBS, NUMPUTS)) {
      if (g.PRSO == HANDS || g.PRSO == FEET) {
        await WET_AND_SLIPPERY();
        return true;
      }
      await PRSO_INTO_SOAPY_WATER();
      return true;
    }
    return false;
  } else if ((await ENTERING$()) || isVerb(V.CLIMB_ON, V.CLIMB_DOWN)) {
    if (g.IN_DISH$ == 0) {
      await ENTER_DISH();
      return true;
    }
    await ALREADY_IN();
    return true;
  } else if (isVerb(V.SIT, V.LIE_DOWN, V.SWIM, V.DIVE, V.LEAP)) {
    if (g.IN_DISH$ == 0) {
      await ENTER_DISH();
      return true;
    }
    tell("You're wet enough already.\n");
    return true;
  } else if (isVerb(V.CLIMB_UP) || (await EXITING$())) {
    if (g.IN_DISH$ == 0) {
      await NOT_IN();
      return true;
    }
    await EXIT_DISH();
    return true;
  } else if (isVerb(V.TOUCH, V.REACH_IN, V.KISS) && (g.PRSI == false || g.PRSI == HANDS)) {
    await WET_AND_SLIPPERY();
    return true;
  } else if (isVerb(V.DRINK, V.DRINK_FROM)) {
    tell("Yuck! ");
    await CTHE_PRINT();
    tell(" tastes awful.\n");
    return true;
  } else if (isVerb(V.SMELL)) {
    tell("Its lemony scent reminds you of dishwashing liquid.\n");
    return true;
  } else if (isVerb(V.EAT, V.BITE)) {
    await IMPOSSIBLE();
    return true;
  } else {
    return false;
  }
}

