async function DESCRIBE_LUMP(context = false) {
  if (context == M_OBJDESC) {
    tell("A ");
    if (hasFlag(LUMP, CHILLY)) {
      tell("glowing ");
    } else {
      tell("dark ");
    }
    tell(D(LUMP), " lies half-buried at your feet");
    if (first(LUMP)) {
      tell(". On it you see ");
      await PRINT_CONTENTS(LUMP);
    }
    tell(".");
    return true;
  } else {
    return false;
  }
}

async function LUMP_F() {
  let obj = 0, nxt = 0;
  if (!(g.SUITED$ == 0) && !(hasFlag(LUMP, TRYTAKE)) && !(await GOT$(LUMP))) {
    await CANT_REACH_THRU_FILM();
    return M_FATAL;
  }
  if (!(g.NOW_PRSI$ == 0)) {
    if (isVerb(V.PUT_UNDER)) {
      await PERFORM(V.LOOSEN, g.PRSI, g.PRSO);
      return true;
    } else if (isVerb(V.PUT_ON, V.PLUG, V.TOUCH_TO)) {
      if (g.PRSO == HANDS || g.PRSO == ME || g.PRSO == MOUTH) {
        await PERFORM(V.TOUCH, g.PRSI);
        return true;
      } else if (g.PRSO == FEET || g.PRSO == ANKLE) {
        await PERFORM(V.KICK, g.PRSI);
        return true;
      } else if (g.PRSO == POCKET) {
        await WASTE_OF_TIME();
        return true;
      } else if (g.PRSO == ICE) {
        await COOL_LUMP();
        return true;
      } else if (g.PRSO == PARASOL || g.PRSO == SPADE) {
        await MAGNETIC();
        return true;
      } else if (hasFlag(g.PRSI, CHILLY) && (g.PRSO == EBAG || g.PRSO == SOGGY) && first(g.PRSO)) {
        await EMPTY_PRSO_FIRST();
        return true;
      } else if (hasFlag(g.PRSI, CHILLY) && (g.PRSO == OCRANE || g.PRSO == BAD_CRANE || g.PRSO == SHROUD || g.PRSO == BANDAGE || g.PRSO == BAG || g.PRSO == EBAG || g.PRSO == SOGGY)) {
        await VANISH();
        await CTHE_PRINT();
        tell(" bursts into flame when it touches the ", D(g.PRSI), ". Soon there's nothing left of it.\n");
        return true;
      } else if (hasFlag(g.PRSO, FERRIC)) {
        if (hasFlag(g.PRSO, TAKEABLE) && (loc(g.PRSO) == PLAYER) && (getProp(g.PRSO, P.SIZE) < 6)) {
          move(g.PRSO, g.PRSI);
          await CTHE_PRINT();
          tell(" attaches itself to the ");
          if (hasFlag(g.PRSI, CHILLY)) {
            tell("hot ");
          }
          tell(D(g.PRSI), " with a sharp ");
          (await ITALICIZE("click."));
          crlf();
          return true;
        }
        await MAGNETIC();
        return true;
      } else if (isVerb(V.TOUCH_TO)) {
        tell("Nothing happens.\n");
        return true;
      }
      await PRSO_SLIDES_OFF_PRSI();
      return true;
    }
    return false;
  } else if (isVerb(V.EXAMINE, V.LOOK_ON)) {
    await CTHE_PRINT();
    tell(" is roughly the size and shape of a large grapefruit. Its ", D(CSURFACE));
    if (hasFlag(g.PRSO, CHILLY)) {
      tell(" glows with heat");
    } else {
      tell(" is black and scorched");
    }
    if (first(g.PRSO)) {
      tell(". ", S(g.YOU_SEE));
      await PRINT_CONTENTS(g.PRSO);
      tell(" clinging to it");
    }
    tell(S(g.PERIOD));
    return true;
  } else if (isVerb(V.TAKE_WITH, V.DIG, V.LOOSEN)) {
    if (g.PRSI == HANDS) {
      if (loc(SPADE) == PLAYER) {
        await SPADE_LUMP();
        return true;
      }
      await PERFORM(V.TOUCH, g.PRSO);
      return true;
    } else if (g.PRSI == POCKET || g.PRSI == MOUTH || g.PRSI == ANKLE || g.PRSI == HEAD || g.PRSI == EYES) {
      await IMPOSSIBLE();
      return true;
    } else if (g.PRSI == FEET) {
      await PERFORM(V.KICK, g.PRSO);
      return true;
    } else if (g.PRSI == SPADE) {
      await SPADE_LUMP();
      return true;
    } else if (g.PRSI == PARASOL) {
      await CTHEI_PRINT();
      tell(" proves awkward for this purpose.\n");
      return true;
    } else if (g.PRSI == ICE) {
      await COOL_LUMP();
      return true;
    } else if (hasFlag(g.PRSO, CHILLY) && (g.PRSI == OCRANE || g.PRSI == BAD_CRANE || g.PRSI == SHROUD || g.PRSI == BANDAGE || g.PRSI == BAG || g.PRSI == EBAG)) {
      await PERFORM(V.PUT, g.PRSI, g.PRSO);
      return true;
    }
    await WASTE_OF_TIME();
    return true;
  } else if (isVerb(V.TAKE, V.TOUCH, V.PULL, V.PUSH, V.MOVE, V.PUSH_TO, V.TURN, V.RELEASE, V.TAKE_OFF)) {
    if (hasFlag(g.PRSO, TRYTAKE)) {
      await NO_AVAIL();
      return true;
    } else if (hasFlag(g.PRSO, CHILLY)) {
      await TOUCH_LUMP();
      return true;
    } else if (isVerb(V.TAKE)) {
      putProp(g.PRSO, P.DESCFCN, 0);
    }
    return false;
  } else if (isVerb(V.KICK)) {
    if (hasFlag(g.PRSO, TRYTAKE)) {
      await CTHE_PRINT();
      tell(" refuses to budge.\n");
      return true;
    } else if (hasFlag(g.PRSO, CHILLY)) {
      tell("Your sneaker sizzles with intense heat.\n");
      return true;
    }
    return false;
  } else {
    return false;
  }
}

