async function COTTAGE_F() {
  let in_ = false;
  if (g.HERE == IN_COTTAGE) {
    in_ = true;
  }
  if (isVerb(V.EXAMINE)) {
    if (g.HERE == ON_BLUFF) {
      await PERFORM(V.EXAMINE, COTTAGE_DOOR);
      return true;
    } else if (g.HERE == IN_GARDEN) {
      await PERFORM(V.EXAMINE, GARDEN_DOOR);
      return true;
    }
    await V_LOOK();
    return true;
  } else if (isVerb(V.LOOK_INSIDE, V.SEARCH)) {
    if (in_ == 0) {
      await CANT_SEE_MUCH();
      return true;
    }
    await V_LOOK();
    return true;
  } else if (await ENTERING$()) {
    if (g.HERE == IN_GARDEN) {
      await DO_WALK(P.WEST);
      return true;
    } else if (g.HERE == ON_BLUFF) {
      await DO_WALK(P.EAST);
      return true;
    }
    await ALREADY_IN();
    return true;
  } else if (await EXITING$()) {
    if (in_ == 0) {
      await NOT_IN();
      return true;
    }
    await V_WALK_AROUND();
    return true;
  } else {
    return false;
  }
}

