async function GENERIC_ARBS_F(table) {
  if (g.HERE == ARBORETUM || g.HERE == NORTH_ARBOR || g.HERE == SOUTH_ARBOR || g.HERE == ARBOR_TOP) {
    return ARBOR;
  } else if ((W.ARBORVITA == g.P_NAM || W.ARBORVITA == g.P_XNAM) || (W.VITAES == g.P_NAM || W.VITAES == g.P_XNAM)) {
    return ARBS;
  }
  return HEDGE;
}

async function HEDGE_F() {
  let in_ = false;
  if (g.HERE == SWPATH || g.HERE == ARBORETUM || g.HERE == SEPATH || g.HERE == NORTH_ARBOR || g.HERE == ARBOR_TOP || g.HERE == SOUTH_ARBOR) {
    in_ = true;
  }
  if (!(g.NOW_PRSI$ == 0)) {
    if (isVerb(V.THROW_OVER, V.PUT_BEHIND)) {
      if (g.HERE == NORTH_ARBOR || g.HERE == ARBOR_TOP || g.HERE == SOUTH_ARBOR) {
        await CANT_FROM_HERE();
        return true;
      }
      move(g.PRSO, getProp(g.HERE, P.OVER_HEDGE));
      g.P_IT_OBJECT = NOT_HERE_OBJECT;
      await CTHE_PRINT();
      tell(" sails over the top of the hedge and disappears.\n");
      return true;
    } else if (isVerb(V.PUT_ON)) {
      await PRSI_TOP_TOO_HIGH();
      return true;
    }
    return false;
  } else if (isVerb(V.EXAMINE)) {
    await CTHE_PRINT(HEDGE);
    tell(" is a dense tangle of ", D(ARBS), ", thirty feet high");
    if (g.HERE == AT_TRELS) {
      tell(S(g.PA), "pair of ", D(TRELS), " leads inside");
    } else if (g.HERE == DOCKSIDE) {
      tell(". It ends at the river's edge");
    }
    printS(g.PERIOD);
    return true;
  } else if (isVerb(V.LOOK_INSIDE, V.LOOK_BEHIND, V.SEARCH)) {
    if (g.HERE == AT_TRELS) {
      await CANT_SEE_MUCH();
      return true;
    }
    await CTHE_PRINT(HEDGE);
    tell(" is much too thick.\n");
    return true;
  } else if (isVerb(V.FOLLOW)) {
    if (g.HERE == DOCKSIDE) {
      await DO_WALK(P.WEST);
      return true;
    } else if (g.HERE == FCLEARING) {
      await DO_WALK(P.EAST);
      return true;
    }
    await V_WALK_AROUND();
    return true;
  } else if (await ENTERING$()) {
    if (g.HERE == AT_TRELS) {
      await DO_WALK(P.IN);
      return true;
    } else if (!(in_ == 0)) {
      await V_WALK_AROUND();
      return true;
    }
    await DO_WALK(P.SOUTH);
    return true;
  } else if (isVerb(V.CLIMB_ON, V.CLIMB_OVER, V.CLIMB_UP, V.SIT, V.STAND_ON, V.LIE_DOWN, V.LEAP)) {
    await TOO_HIGH();
    return true;
  } else if (await EXITING$()) {
    if (!(in_ == 0)) {
      await V_WALK_AROUND();
      return true;
    }
    await NOT_IN();
    return true;
  } else if (isVerb(V.CLIMB_DOWN, V.TAKE_OFF)) {
    await NOT_IN(g.PRSO, true);
    return true;
  } else if (isVerb(V.FOLLOW)) {
    await V_WALK_AROUND();
    return true;
  } else if (isVerb(V.SMELL)) {
    await SMELL_HEDGE();
    return true;
  } else {
    return false;
  }
}

