async function CAGE_F() {
  if (!(g.NOW_PRSI$ == 0)) {
    if (isVerb(V.PUT)) {
      if (!(hasFlag(g.PRSI, OPENED))) {
        (await YOUD_HAVE_TO("open", g.PRSI));
        return true;
      } else if (g.PRSO == MEEP) {
        setFlag(g.PRSO, TOUCHED);
        move(g.PRSO, g.PRSI);
        tell(S(g.CTHEMEEP), "pecks furiously at ", D(HANDS), ", but you grit your teeth and stuff the protesting bird into the cage.\n");
        return true;
      } else if (g.PRSO == LEM) {
        move(g.PRSO, g.PRSI);
        await CTHE_PRINT();
        tell(" sinks its teeth into your thumb when it sees the cage. But you jam it inside anyway.\n");
        if (!(hasFlag(g.PRSI, BORING))) {
          setFlag(g.PRSI, BORING);
          await UPDATE_SCORE();
        }
        return true;
      } else if (getProp(g.PRSO, P.SIZE) > 3) {
        await PRSO_WONT_FIT();
      } else {
        move(g.PRSO, g.PRSI);
        tell("You put ");
        await THE_PRINT();
        tell(" into ");
        await THEI_PRINT();
        tell(S(g.PERIOD));
      }
      if ((g.PRSO == BAG) && !(g.CCNT == 0) && (loc(MEEP) == g.HERE)) {
        clearFlag(BAG, SEEN);
        await MEEP_SEES_BAG();
      }
      return true;
    } else if (isVerb(V.PUT_ON)) {
      await PRSO_SLIDES_OFF_PRSI();
      return true;
    }
    return false;
  } else if (isVerb(V.EXAMINE)) {
    tell("The");
    await OPEN_CLOSED(g.PRSO);
    tell(" is cunningly woven of brown and yellow wicker");
    if (await SEE_ANYTHING_IN$(g.PRSO)) {
      tell(". Peering between the slats, you see ");
      await PRINT_CONTENTS(g.PRSO);
    }
    printS(g.PERIOD);
    return true;
  } else if (isVerb(V.OPEN, V.OPEN_WITH) && (g.PRSI == false || g.PRSI == HANDS) && !(hasFlag(g.PRSO, OPENED))) {
    setFlag(g.PRSO, OPENED);
    clearFlag(LEM, CHILLY);
    tell("You open the ", D(g.PRSO), S(g.PERIOD));
    if ((loc(MAGPIE) == g.PRSO) && !(g.LIT$ == 0)) {
      tell("\n");
      await CTHE_PRINT(MAGPIE);
      tell(" flutters out of the cage and ");
      if (!(g.SUITED$ == 0)) {
        await FREE_MAG(FILM);
        return true;
      } else if ((g.HERE == IN_CLOSET) && !(hasFlag(CLOSET_DOOR, OPENED))) {
        await FREE_MAG(CLOSET);
        return true;
      } else if (g.HERE == IN_COTTAGE) {
        if (hasFlag(COTTAGE_DOOR, OPENED) || hasFlag(GARDEN_DOOR, OPENED)) {
          await EXIT_MAGPIE();
          tell("soars through the open door.\n");
          return true;
        }
        await FREE_MAG(COTTAGE);
        return true;
      }
      tell("soars", S(g.OUTASITE));
      await EXIT_MAGPIE();
      return true;
    } else if (loc(LEM) == g.PRSO) {
      clearFlag(LEM, SEEN);
      await I_LEM();
      return true;
    }
    return true;
  } else {
    return false;
  }
}

