async function COCO_F() {
  if (!(g.NOW_PRSI$ == 0)) {
    if (isVerb(V.THROW, V.THROW_OVER) && hasFlag(g.PRSI, TRYTAKE)) {
      await PERFORM(g.PRSA, g.PRSO, LAGOON);
      return true;
    }
    return false;
  } else if (hasFlag(COCO, TRYTAKE) && inTable(g.PRSA, g.TOUCHVERBS, NTOUCHES) && inTable(g.PRSA, g.HURTVERBS, NHVERBS)) {
    tell(S(g.CANT), "reach the ", D(COCO), " from here.\n");
    return true;
  } else if (!(g.NOW_PRSI$ == 0)) {
    return false;
  } else if (isVerb(V.EXAMINE)) {
    await CTHE_PRINT();
    if (loc(g.PRSO) == ISLET) {
      tell(" under the tree");
    } else if (hasFlag(g.PRSO, CHILLY)) {
      tell(" floating in the water");
    }
    tell(" looks especially plump and juicy.\n");
    return true;
  } else if (isVerb(V.CUT, V.RIP, V.HIT, V.MUNG, V.OPEN, V.OPEN_WITH)) {
    if (g.PRSI == false || g.PRSI == HANDS || g.PRSI == FEET) {
      await BEST_KARATE();
      return true;
    } else if (g.PRSI == AXE || g.PRSI == LUMP || g.PRSI == SPADE) {
      if (loc(g.PRSO) == PLAYER) {
        tell("While holding the ", D(g.PRSO), "? Unwise.\n");
        return true;
      }
      move(OCOCO, loc(g.PRSO));
      move(MILK, loc(OCOCO));
      remove(g.PRSO);
      g.P_IT_OBJECT = OCOCO;
      g.DRIBBLE = 3;
      await QUEUE(I_MILK.id, -1);
      tell("You deal the ", D(g.PRSO), " a mortal blow with ");
      await THEI_PRINT();
      tell(S(g.PCR));
      await SAY_MILK();
      await UPDATE_SCORE();
      return true;
    } else if (isVerb(V.HIT)) {
      await DULL_THUD();
      return true;
    }
    (await NOT_LIKELY(g.PRSI, "would affect the coconut"));
    return true;
  } else if (isVerb(V.SHAKE)) {
    tell("You hear liquid slooshing around inside.\n");
    return true;
  } else {
    return false;
  }
}

