async function MULTIDOOR$() {
  let x = 0;
  if (!(await NOUN_USED$(W.DOORS, W.DOORWAYS))) {
    return false;
  } else if (inTable(g.PRSA, g.PUTVERBS, NUMPUTS)) {
    (await ONE_AT_A_TIME("door"));
    return M_FATAL;
  }
  g.P_THEM_OBJECT = RIGHT_DOOR;
  if (g.NOW_PRSI$ == 0) {
    put(g.P_NAMW, 0, W.DOOR);
    put(g.P_OFW, 0, false);
    await CTHE_PRINT(RIGHT_DOOR);
    tell(": ");
    x = await PERFORM(g.PRSA, RIGHT_DOOR, g.PRSI);
    if (!(x == false || x == M_FATAL)) {
      tell("\n");
      await CTHE_PRINT(LEFT_DOOR);
      tell(": ");
      x = await PERFORM(g.PRSA, LEFT_DOOR, g.PRSI);
    }
    return true;
  } else if (!(g.PRSI == 0)) {
    put(g.P_NAMW, 1, W.DOOR);
    put(g.P_OFW, 1, false);
    await CTHE_PRINT(RIGHT_DOOR);
    tell(": ");
    x = await PERFORM(g.PRSA, g.PRSO, RIGHT_DOOR);
    if (!(x == false || x == M_FATAL)) {
      tell("\n");
      await CTHE_PRINT(LEFT_DOOR);
      tell(": ");
      x = await PERFORM(g.PRSA, g.PRSO, LEFT_DOOR);
    }
    return true;
  } else {
    return false;
  }
}

