async function HANDLE_DESERT_ROAD$(ddir, tstr, dstr) {
  if (await EXAMINING_ROAD$()) {
    tell("The road leads ");
    if (!(g.HERE == AT_ZERO)) {
      tell(S(tstr));
      if (await GLOBAL_IN$(DTOWER, g.HERE)) {
        tell(" towards the ", D(DTOWER), ",");
      }
      tell(" and ");
    }
    tell(S(dstr), " ", S(g.INTO_DESERT), S(g.PERIOD));
    return true;
  } else if (await USING_ROAD$()) {
    if (g.HERE == AT_ZERO) {
      await DO_WALK(ddir);
      return true;
    }
    await V_WALK_AROUND();
    return true;
  } else if (await EXITING$()) {
    await V_WALK_AROUND();
    return true;
  } else {
    return false;
  }
}

