async function BOOK_F() {
  if (!(g.NOW_PRSI$ == 0)) {
    if (isVerb(V.PUT, V.EMPTY_INTO)) {
      if (!(hasFlag(g.PRSI, OPENED))) {
        await ITS_CLOSED(g.PRSI);
        return true;
      }
      await CTHE_PRINT();
      if (g.PRSO == MARKER) {
        move(g.PRSO, g.PRSI);
        tell(" slips between the pages.\n");
        return true;
      } else if (getProp(g.PRSO, P.SIZE) > 1) {
        tell(" wouldn't fit in the book.\n");
        return true;
      }
      tell(" falls out of the book and ");
      await LANDS_AT_YOUR_FEET();
      return true;
    } else if (isVerb(V.PUT_ON)) {
      await PRSO_SLIDES_OFF_PRSI();
      return true;
    }
    return false;
  } else if (isVerb(V.EXAMINE, V.LOOK_ON)) {
    tell("It's a cheap paperback called ");
    (await ITALICIZE("Desert Island Decameron."));
    crlf();
    return true;
  } else if (isVerb(V.OPEN, V.OPEN_WITH, V.UNFOLD) && (g.PRSI == false || g.PRSI == HANDS) && !(hasFlag(g.PRSO, OPENED))) {
    setFlag(g.PRSO, OPENED);
    if (loc(MARKER) == g.PRSO) {
      move(MARKER, g.HERE);
      g.P_IT_OBJECT = MARKER;
      tell("A ", D(MARKER), " falls out of the book as you open it.\n");
      return true;
    }
    tell("You open the ", D(g.PRSO), S(g.PERIOD));
    return true;
  } else if (isVerb(V.READ, V.LOOK_ON, V.LOOK_INSIDE, V.SEARCH, V.TURN, V.TURN_TO)) {
    if (!(loc(g.PRSO) == PLAYER)) {
      (await YOUD_HAVE_TO("be holding", g.PRSO));
      return true;
    } else if (!(hasFlag(g.PRSO, OPENED))) {
      await PERFORM(V.OPEN, g.PRSO);
      crlf();
    }
    tell("You flip through the book, but nothing catches your eye.\n");
    return true;
  } else {
    return false;
  }
}

