async function SPILL_MILL() {
  let l = 0;
  if (eq(loc(CAGE), PLAYER, IN_MILL)) {
    await DO_DROWN();
  }
  l = loc(WTK);
  if (l == 0) {
  } else if ((l == PLAYER || l == IN_MILL) || (loc(l) == PLAYER)) {
    setFlag(WTK, CHILLY);
  }
  l = loc(BAG);
  if (l == 0) {
  } else if ((l == PLAYER || l == IN_MILL) || (loc(l) == PLAYER)) {
    move(SOGGY, l);
    remove(BAG);
    g.APPETITE = 0;
    g.CCNT = 0;
  }
  l = loc(EBAG);
  if (l == 0) {
  } else if ((l == PLAYER || l == IN_MILL) || (loc(l) == PLAYER)) {
    await MOVE_ALL(EBAG, SOGGY);
    move(SOGGY, l);
    remove(EBAG);
  }
  l = loc(MEEP);
  if (l == PLAYER || l == IN_MILL) {
    await EXIT_MEEP();
    move(DMEEP, l);
    setFlag(DMEEP, CHILLY);
  }
  await DEQUEUE(I_MILL.id);
  setFlag(BINOS, TOUCHED);
  putProp(BINOS, P.FDESC, 0);
  await DROP_ALL(UNDER_WATER);
  clearFlag(IN_CIST, TOUCHED);
  clearFlag(UNDER_WATER, TOUCHED);
  clearFlag(UNDERM, TOUCHED);
  if (!(g.BREATH_HELD$ == 0)) {
    g.BREATH_HELD$ = 1;
  }
  (await ITALICIZE("Crack!"));
  tell(" The ", D(LANDING), " tips wildly under your feet. You manage a brief, hysterical shriek...");
  await CARRIAGE_RETURNS();
  tell("... and your mouth fills with water", S(g.PCR));
  await GOTO(IN_CIST);
  await MOVE_ALL(IN_MILL, UNDER_WATER);
  return true;
}

async function DO_DROWN() {
  if (loc(LEM) == CAGE) {
    await EXIT_LEM();
    setFlag(DLEM, CHILLY);
    move(DLEM, CAGE);
  }
  if (loc(MAGPIE) == CAGE) {
    await EXIT_MAGPIE();
    setFlag(DMAGPIE, CHILLY);
    move(DMAGPIE, CAGE);
  }
  if (loc(MEEP) == CAGE) {
    await EXIT_MEEP();
    setFlag(DMEEP, CHILLY);
    move(DMEEP, CAGE);
  }
  return true;
}

