async function BOX_F() {
  let l = false;
  l = await BOX_LOCKED$();
  if (!(g.NOW_PRSI$ == 0)) {
    if (isVerb(V.PUT)) {
      if (!(hasFlag(g.PRSI, OPENED))) {
        await ITS_CLOSED(g.PRSI);
        return true;
      } else if (await BAG_IN_BOX$()) {
        return true;
      }
      return false;
    } else if (isVerb(V.PUT_ON) && (await BAG_IN_BOX$())) {
      return true;
    }
    return false;
  } else if (isVerb(V.EXAMINE, V.LOOK_ON)) {
    tell("The");
    await OPEN_CLOSED(g.PRSO);
    tell(" is several feet in length");
    if (!(l == 0)) {
      tell(", and secured with a steel ", D(PADLOCK));
    }
    if (!(hasFlag(g.PRSO, OPENED)) && (await SEE_ANYTHING_IN$(g.PRSO))) {
      tell(". On it you see ");
      await PRINT_CONTENTS(g.PRSO);
    }
    printS(g.PERIOD);
    return true;
  } else if (isVerb(V.LOOK_INSIDE, V.SEARCH)) {
    if (hasFlag(g.PRSO, OPENED)) {
      printS(g.YOU_SEE);
      await PRINT_CONTENTS(g.PRSO);
      tell(" inside the box.\n");
      return true;
    }
    await ITS_CLOSED();
    return true;
  } else if (isVerb(V.OPEN, V.OPEN_WITH)) {
    if (hasFlag(g.PRSO, OPENED)) {
      (await ITS_ALREADY("open"));
      return true;
    } else if (g.PRSI == false || g.PRSI == HANDS) {
      if ((loc(PADLOCK) == g.PRSO) && hasFlag(PADLOCK, NODESC)) {
        g.P_IT_OBJECT = PADLOCK;
        (await YOUD_HAVE_TO("take off", PADLOCK));
        return true;
      }
      await OPEN_BOX();
      return true;
    } else if (g.PRSI == TKEY) {
      if (!(l == 0)) {
        l = await PERFORM(V.UNLOCK, PADLOCK, g.PRSI);
        crlf();
        await OPEN_BOX();
        return true;
      }
      await BOX_NOT_LOCKED();
      return true;
    } else if (g.PRSI == AXE || g.PRSI == SPADE) {
      await HURT_BOX();
      return true;
    }
    (await NOT_LIKELY(g.PRSI, "would open the box"));
    return true;
  } else if (isVerb(V.UNLOCK)) {
    if (l == 0) {
      await BOX_NOT_LOCKED();
      return true;
    } else if (g.PRSI == TKEY) {
      l = await PERFORM(V.UNLOCK, PADLOCK, g.PRSI);
      crlf();
      await OPEN_BOX();
      return true;
    }
    (await NOT_LIKELY(g.PRSI, "would unlock the box"));
    return true;
  } else if (isVerb(V.CLOSE)) {
    if (!(hasFlag(g.PRSO, OPENED))) {
      (await ITS_ALREADY("closed"));
      return true;
    } else if (loc(MEEP) == g.PRSO) {
      (await YOUD_HAVE_TO("take out", MEEP));
      return true;
    }
    clearFlag(g.PRSO, OPENED);
    clearFlag(g.PRSO, CONTAINER);
    setFlag(g.PRSO, SURFACE);
    await MOVE_ALL(g.PRSO, IN_BOX);
    tell("You swing the lid of the box shut.\n");
    return true;
  } else if (isVerb(V.HIT, V.CUT, V.MUNG, V.KICK)) {
    if (isVerb(V.KICK) || (g.PRSI == false || g.PRSI == HANDS || g.PRSI == FEET)) {
      await BEST_KARATE();
      return true;
    } else if (g.PRSI == LUMP || g.PRSI == AXE || g.PRSI == SPADE) {
      await HURT_BOX();
      return true;
    }
    (await NOT_LIKELY(g.PRSI, "would affect the box"));
    return true;
  } else if (isVerb(V.LOCK) && !(g.PRSI == 0)) {
    if (!(l == 0)) {
      (await ITS_ALREADY("locked"));
      return true;
    } else if (g.PRSI == TKEY) {
      tell(S(g.DONT), "need the key to do that.\n");
      return true;
    } else if ((g.PRSI == PADLOCK) || ((g.PRSI == HANDS) && (loc(PADLOCK) == PLAYER))) {
      if (hasFlag(g.PRSO, OPENED)) {
        l = await PERFORM(V.CLOSE, g.PRSO);
        crlf();
      }
      if (!(loc(PADLOCK) == g.PRSO)) {
        l = await PERFORM(V.PUT, PADLOCK, g.PRSO);
        crlf();
      }
      l = await PERFORM(V.CLOSE, PADLOCK);
      return true;
    } else if (g.PRSI == HANDS) {
      tell(S(g.DONT), "have the ", D(PADLOCK), S(g.PERIOD));
      return true;
    }
    (await NOT_LIKELY(g.PRSI, "would lock the box"));
    return true;
  } else if (isVerb(V.LOOK_UNDER) || inTable(g.PRSA, g.MOVEVERBS, NMVERBS)) {
    await PRSO_TOO_BIG();
    return true;
  } else {
    return false;
  }
}

async function HURT_BOX() {
  tell("You'd probably damage the box's contents", S(g.IF_YOU_DID));
  return true;
}

async function BOX_NOT_LOCKED() {
  tell("The box isn't locked.\n");
  return true;
}

async function OPEN_BOX() {
  let obj = 0, nxt = 0, cnt = 0, _1st = 0;
  obj = first(BOX);
  loop1: for (;;) {
    if (obj == 0) {
      break loop1;
    }
    nxt = next(obj);
    if (hasFlag(obj, TAKEABLE)) {
      clearFlag(obj, NODESC);
      move(obj, AT_ZERO);
      _1st = obj;
      ++cnt;
    }
    obj = nxt;
  }
  if (cnt == 0) {
    tell("You swing open the lid of the box");
  } else {
    if (cnt == 1) {
      await CTHE_PRINT(_1st);
    } else {
      tell("Everything");
    }
    tell(" slides off the lid of the box as you swing it open");
  }
  setFlag(BOX, OPENED);
  setFlag(BOX, CONTAINER);
  clearFlag(BOX, SURFACE);
  await MOVE_ALL(IN_BOX, BOX);
  tell(", revealing ");
  await PRINT_CONTENTS(BOX);
  tell(" inside.\n");
  return true;
}

async function PADLOCK_F() {
  if (!(g.NOW_PRSI$ == 0)) {
    if (isVerb(V.PUT)) {
      if (g.PRSO == TKEY) {
        move(g.PRSO, g.PRSI);
        tell("You slide the ", D(g.PRSO));
      } else if (getProp(g.PRSO, P.SIZE) > 1) {
        tell("You'd never fit ");
        await THE_PRINT();
      } else if (loc(TKEY) == g.PRSI) {
        (await YOUD_HAVE_TO("take out", TKEY));
        return true;
      } else {
        await CTHE_PRINT();
        tell(" doesn't fit");
      }
      tell(" into the ", D(g.PRSI), S(g.PERIOD));
      return true;
    }
    return false;
  } else if (isVerb(V.EXAMINE)) {
    tell("The ");
    if (!(hasFlag(g.PRSO, LOCKED))) {
      tell("open ");
    }
    tell(D(g.PRSO), " is a formidable hunk of hardened steel.\n");
    return true;
  } else if (isVerb(V.OPEN, V.OPEN_WITH, V.UNLOCK, V.PICK)) {
    if (!(hasFlag(g.PRSO, LOCKED))) {
      await CTHE_PRINT();
      tell(" isn't locked.\n");
      return true;
    } else if (g.PRSI == false || g.PRSI == HANDS || g.PRSI == TKEY) {
      if ((g.PRSI == TKEY) || (loc(TKEY) == PADLOCK)) {
        await OPEN_PADLOCK();
        return true;
      }
      await HOW$();
      return true;
    }
    (await NOT_LIKELY(g.PRSI, "would open the padlock"));
    return true;
  } else if (isVerb(V.CLOSE, V.LOCK)) {
    if (hasFlag(g.PRSO, LOCKED)) {
      (await ITS_ALREADY("closed"));
      return true;
    } else if (!(g.PRSI == 0) && !(g.PRSI == HANDS)) {
      tell(S(g.DONT), "need ");
      await THEI_PRINT();
      tell(" to close the ", D(g.PRSO), S(g.PERIOD));
      return true;
    }
    setFlag(g.PRSO, LOCKED);
    tell("You snap the ", D(g.PRSO), " shut.\n");
    if ((loc(g.PRSO) == BOX) && !(hasFlag(BOX, OPENED))) {
      clearFlag(g.PRSO, TAKEABLE);
      setFlag(g.PRSO, NODESC);
      setFlag(g.PRSO, NOALL);
      tell("\nThe box is locked again.\n");
    }
    return true;
  } else if (isVerb(V.TAKE, V.PULL, V.MOVE, V.LOOSEN, V.PUSH, V.PUSH_TO, V.RAISE, V.LOWER, V.SHAKE, V.KICK, V.RELEASE, V.TAKE_OFF) && (await BOX_LOCKED$())) {
    await CTHE_PRINT();
    tell(" is firmly locked onto the box.\n");
    return true;
  } else if (isVerb(V.LOOK_INSIDE, V.REACH_IN)) {
    await IMPOSSIBLE();
    return true;
  } else {
    return false;
  }
}

async function OPEN_PADLOCK() {
  clearFlag(PADLOCK, LOCKED);
  setFlag(PADLOCK, TAKEABLE);
  clearFlag(PADLOCK, NOALL);
  if (loc(TKEY) == PADLOCK) {
    await CTHE_PRINT(PADLOCK);
  } else {
    move(TKEY, PADLOCK);
    tell("You slip the key into the ", D(PADLOCK), ". It");
  }
  tell(" unlocks with a smart little snap.\n");
  if (!(hasFlag(PADLOCK, TOUCHED))) {
    setFlag(PADLOCK, TOUCHED);
    await UPDATE_SCORE();
  }
  return true;
}

