async function BREAKER_F() {
  if (!(g.NOW_PRSI$ == 0)) {
    return false;
  } else if (isVerb(V.EXAMINE)) {
    tell("The heavy-duty ", D(g.PRSO), " looks like something out of a Frankenstein movie. Its broad handle is ");
    if (hasFlag(g.PRSO, OPENED)) {
      tell("open.\n");
      return true;
    }
    tell("closed.\n");
    return true;
  } else if (isVerb(V.LAMP_OFF, V.OPEN, V.OPEN_WITH, V.RAISE, V.PULL, V.LOOSEN) && (g.PRSI == false || g.PRSI == HANDS)) {
    if (hasFlag(g.PRSO, OPENED)) {
      (await ITS_ALREADY("open"));
      return true;
    }
    setFlag(g.PRSO, OPENED);
    tell("You lift the handle of the ", D(g.PRSO), S(g.PERIOD));
    return true;
  } else if (isVerb(V.LAMP_ON, V.CLOSE, V.LOWER, V.PUSH) && (g.PRSI == false || g.PRSI == HANDS)) {
    if (hasFlag(g.PRSO, OPENED)) {
      clearFlag(g.PRSO, OPENED);
      setFlag(g.PRSO, BORING);
      tell("You close the handle of the ", D(g.PRSO), S(g.PERIOD));
      if (!(await HEAR_BAKER$())) {
        return true;
      }
      tell("\n\"Hold on, ", D(ABLE), ". X just woke up again.\"\n\nA sigh of relief. \"Sounds like a wet line somewhere.\"\n\n\"The kid's keepin' an eye on it, ", D(PITTS), ". If it dies again");
      if (g.MINUTES < 29) {
        tell(" before the sequencer takes over");
      }
      tell(", we're gonna have to scrub.\"\n\n\"Roger, ", D(BAKER), ". Lotta crossed fingers up here.\"\n");
      await UPDATE_SCORE();
      return true;
    }
    (await ITS_ALREADY("closed"));
    return true;
  } else if (isVerb(V.TURN, V.MOVE)) {
    if (hasFlag(g.PRSO, OPENED)) {
      await PERFORM(V.LAMP_ON, g.PRSO, g.PRSI);
      return true;
    }
    await PERFORM(V.LAMP_OFF, g.PRSO, g.PRSI);
    return true;
  } else if (isVerb(V.TAKE, V.LOOSEN, V.UNSCREW, V.UNSCREW_FROM)) {
    await FIRMLY_ATTACHED(g.PRSO, PANEL);
    return true;
  } else {
    return false;
  }
}

