async function SLIDER_F() {
  let old = 0, f = false;
  if (!(g.NOW_PRSI$ == 0)) {
    return false;
  } else if (isVerb(V.EXAMINE, V.LOOK_ON, V.READ)) {
    await PRSO_CALIBRATED();
    if (hasFlag(WTK, FLIPPED)) {
      tell(", all printed backwards");
    }
    await NOW_SET_TO();
    tell(N(g.TFREQ), S(g.PERIOD));
    return true;
  } else if (isVerb(V.TURN_TO, V.PUSH_TO, V.TUNE_TO, V.POINT_AT)) {
    if (hasFlag(g.PRSO, FLIPPED)) {
      f = true;
    }
    if (g.PRSI == INTNUM) {
      if (await RANGE_ERROR$(g.TFREQ)) {
        return true;
      }
      g.P_IT_OBJECT = WTK;
      g.TFREQ = g.P_NUMBER;
      await TILL_POINTS();
      if (hasFlag(RDIAL, SEEN) && (g.TFREQ == g.MAGICFREQ) && !(hasFlag(g.PRSO, SEEN))) {
        setFlag(g.PRSO, SEEN);
        await UPDATE_SCORE(3);
      }
      return true;
    } else if (g.PRSI == RIGHT) {
      if (((f == 0) && (g.TFREQ == 80)) || (!(f == 0) && (g.TFREQ == 20))) {
        await FAR_AS_IT_GOES();
        return true;
      }
      old = f == 0 ? (g.TFREQ + 5) : (g.TFREQ - 5);
      if ((f == 0) && (old > 79)) {
        old = 80;
      } else if (!(f == 0) && (old < 20)) {
        old = 20;
      }
      g.TFREQ = old;
      (await MOVE_TO_RL("right"));
      return true;
    } else if (g.PRSI == LEFT) {
      if (((f == 0) && (g.TFREQ == 20)) || (!(f == 0) && (g.TFREQ == 80))) {
        await FAR_AS_IT_GOES();
        return true;
      }
      old = f == 0 ? (g.TFREQ - 5) : (g.TFREQ + 5);
      if ((f == 0) && (old < 20)) {
        old = 20;
      } else if (!(f == 0) && (old > 79)) {
        old = 80;
      }
      g.TFREQ = old;
      (await MOVE_TO_RL("left"));
      return true;
    }
    await HOW_TO_USE_TUNER();
    return true;
  } else if (isVerb(V.SPIN, V.TURN, V.MOVE, V.PUSH, V.SWING, V.PLAY, V.SHAKE)) {
    old = g.TFREQ;
    loop1: for (;;) {
      g.TFREQ = random(59) + 21;
      if (!(old == g.TFREQ)) {
        break loop1;
      }
    }
    await FIDDLE();
    return true;
  } else if (await HANDLE_TUNER$()) {
    return true;
  } else {
    return false;
  }
}

async function FAR_AS_IT_GOES() {
  await CTHE_PRINT();
  tell(" won't move any more in ", D(RIGHT), S(g.PERIOD));
  return true;
}

