async function RDIAL_F() {
  let old = 0;
  if (!(g.NOW_PRSI$ == 0)) {
    return false;
  } else if (isVerb(V.EXAMINE, V.LOOK_ON, V.READ)) {
    await PRSO_CALIBRATED();
    await NOW_SET_TO();
    if (!(hasFlag(g.PRSO, TOUCHED)) && !(hasFlag(g.PRSO, SEEN))) {
      setFlag(g.PRSO, SEEN);
      loop1: for (;;) {
        g.MAGICFREQ = random(59) + 21;
        if (!(g.MAGICFREQ == g.TFREQ)) {
          break loop1;
        }
      }
      g.RFREQ = g.MAGICFREQ;
      tell(N(g.RFREQ), S(g.PERIOD));
      await UPDATE_SCORE(3);
      return true;
    }
    tell(N(g.RFREQ), S(g.PERIOD));
    return true;
  } else if (isVerb(V.TURN_TO, V.TUNE_TO, V.POINT_AT, V.PUSH_TO)) {
    if (g.PRSI == INTNUM) {
      if (await RANGE_ERROR$(g.RFREQ)) {
        return true;
      }
      setFlag(g.PRSO, TOUCHED);
      g.P_IT_OBJECT = RADIO;
      g.RFREQ = g.P_NUMBER;
      await TILL_POINTS();
      return true;
    } else if (g.PRSI == RIGHT) {
      if (g.RFREQ == 80) {
        await FAR_AS_IT_GOES();
        return true;
      }
      setFlag(g.PRSO, TOUCHED);
      old = g.RFREQ + 5;
      if (old > 79) {
        old = 80;
      }
      g.RFREQ = old;
      (await MOVE_TO_RL("right"));
      return true;
    } else if (g.PRSI == LEFT) {
      if (g.RFREQ == 20) {
        await FAR_AS_IT_GOES();
        return true;
      }
      setFlag(g.PRSO, TOUCHED);
      old = g.RFREQ - 5;
      if (old < 20) {
        old = 20;
      }
      g.RFREQ = old;
      (await MOVE_TO_RL("left"));
      return true;
    }
    await HOW_TO_USE_TUNER();
    return true;
  } else if (isVerb(V.SPIN, V.TURN, V.MOVE, V.PUSH, V.SWING, V.PLAY, V.SHAKE)) {
    setFlag(g.PRSO, TOUCHED);
    old = g.RFREQ;
    loop2: for (;;) {
      g.RFREQ = random(59) + 21;
      if (!(old == g.RFREQ)) {
        break loop2;
      }
    }
    await FIDDLE();
    return true;
  } else if (await HANDLE_TUNER$()) {
    return true;
  } else {
    return false;
  }
}

