async function PHOTO_F(context = false) {
  if ((await NOUN_USED$(W.BOY, W.CHILD, W.KID)) || (await NOUN_USED$(W.WAND))) {
    if (isVerb(V.EXAMINE)) {
      tell("The boy in the ", D(g.PRSO), " seems familiar. Maybe it's the wand he's holding.\n");
      return true;
    } else if (isVerb(V.LOOK_BEHIND, V.LOOK_UNDER, V.LISTEN, V.SMELL) || inTable(g.PRSA, g.TOUCHVERBS, NTOUCHES)) {
      tell(S(g.CANT), "do that to an image in a ", D(g.PRSO), S(g.PERIOD));
      return true;
    }
  }
  if (!(g.NOW_PRSI$ == 0)) {
    if (inTable(g.PRSA, g.PUTVERBS, NUMPUTS)) {
      await NO_GOOD_SURFACE();
      return true;
    }
    return false;
  } else if (isVerb(V.EXAMINE, V.LOOK_ON, V.READ, V.LOOK_INSIDE, V.SEARCH)) {
    tell("The black-and-white ", D(g.PRSO), " shows a boy staring at the camera.\n");
    return true;
  } else if (inTable(g.PRSA, g.TALKVERBS, NTVERBS)) {
    tell("The boy just stares back at you.\n");
    return M_FATAL;
  } else if (isVerb(V.TURN, V.SPIN) && (g.PRSI == false || g.PRSI == HANDS)) {
    tell("There's nothing on the other side.\n");
    return true;
  } else {
    return false;
  }
}

