async function RSWITCH_F() {
  if (!(g.NOW_PRSI$ == 0)) {
    return false;
  } else if (isVerb(V.EXAMINE, V.LOOK_ON, V.READ)) {
    await CTHE_PRINT();
    tell(" on the ", D(RADIO), " is marked POWER, and is turned ");
    if (hasFlag(g.PRSO, OPENED)) {
      tell("off.\n");
      return true;
    }
    tell("on.\n");
    return true;
  } else if (isVerb(V.LAMP_ON, V.CLOSE) && (g.PRSI == false || g.PRSI == HANDS)) {
    if (hasFlag(g.PRSO, OPENED)) {
      await FLIP_RSWITCH();
      return true;
    }
    await CTHE_PRINT();
    tell(" is already on.\n");
    return true;
  } else if (isVerb(V.LAMP_OFF, V.OPEN, V.OPEN_WITH, V.KILL) && (g.PRSI == false || g.PRSI == HANDS)) {
    if (hasFlag(g.PRSO, OPENED)) {
      await CTHE_PRINT();
      tell(" is already off.\n");
      return true;
    }
    await FLIP_RSWITCH();
    return true;
  } else if (isVerb(V.USE, V.TURN, V.MOVE, V.PUSH, V.TOUCH) && (g.PRSI == false || g.PRSI == HANDS)) {
    await FLIP_RSWITCH();
    return true;
  } else if (isVerb(V.TAKE, V.PULL, V.LOOSEN, V.UNSCREW, V.UNSCREW_FROM)) {
    await FIRMLY_ATTACHED(g.PRSO, RADIO);
    return true;
  } else {
    return false;
  }
}

