async function BOOT_SCREEN(intro$ = true) {
  await QUEUE(I_CRANE_APPEARS.id, -1);
  await QUEUE(I_BWOMAN.id, -1);
  await QUEUE(I_AIR_RAID.id, -1);
  await QUEUE(I_BOY.id, -1);
  await PCLEAR();
  g.HERE = PAL_GATE;
  move(PLAYER, g.HERE);
  g.WINNER = PLAYER;
  g.LIT$ = true;
  if (!(intro$ == 0)) {
    tell("\nSharp words between the superpowers. Tanks in East Berlin. And now, reports the BBC, rumors of a satellite blackout. It's enough to spoil your continental breakfast.\n\nBut the world will have to wait. This is the last day of your $599 ", D(LONDON), " Getaway Package, and you're determined to soak up as much of that authentic English ambience as you can. So you've left the tour bus behind, ditched the camera and escaped to Hyde Park for a contemplative stroll through the ", D(GARDENS), S(g.PCR));
  }
  await V_LOOK();
  if (!(g.TR$ == 0)) {
    g.DO_WINDOW = get(g.QUOTES, EMILY);
  }
  return true;
}

